/**
 * What kind of device and browser the app is running on, for the one thing
 * that needs it: offering the right install link ("Lexpad everywhere" in
 * Settings, the cards on Today, Get started). A store link that cannot be
 * used where it is shown — the Chrome Web Store on a phone — is worse than
 * no link, so this is about picking the honest option, not about tracking.
 *
 * The decision is a pure function of what the browser reports, so it can be
 * tested with real user-agent strings; `currentDevice()` feeds it the live
 * values.
 */
import { isDesktopShell, shellPlatform } from './detect.js';

export type DeviceOs = 'android' | 'ios' | 'mac' | 'windows' | 'linux' | 'chromeos' | 'other';

export type DeviceBrowser =
  'chrome' | 'edge' | 'brave' | 'opera' | 'samsung' | 'firefox' | 'safari' | 'other';

/**
 * Where this copy of the app runs: a phone app (Capacitor), the desktop
 * app's window (Tauri), or a browser tab. Only a browser tab is ever offered
 * another app: the stores' rules keep the phone apps from pointing to other
 * platforms, and the desktop app is already the app.
 */
export type DeviceShell = 'android' | 'ios' | 'desktop' | 'web';

export interface Device {
  shell: DeviceShell;
  os: DeviceOs;
  browser: DeviceBrowser;
  /** A phone or tablet: no browser extensions, no desktop app. */
  mobile: boolean;
}

/**
 * User-Agent Client Hints (`navigator.userAgentData`, Chromium only). More
 * trustworthy than the user-agent string where they exist: Chrome on an
 * Android phone asking for the desktop site says "Linux x86_64" in the
 * string but still "Android" here, and Edge, Opera and Brave name
 * themselves in `brands`. Safari and Firefox have none, so the string stays
 * the fallback.
 */
export interface UaData {
  platform: string;
  mobile: boolean;
  brands: readonly { brand: string }[];
}

/** What the browser says about itself. */
export interface DeviceHints {
  userAgent: string;
  /** Client hints, where the browser has them. */
  uaData?: UaData | undefined;
  /** navigator.maxTouchPoints: an iPad asking for the desktop site says "Macintosh". */
  maxTouchPoints: number;
  /** Brave hides itself in the user agent and only answers to navigator.brave. */
  brave: boolean;
  shell: DeviceShell;
}

/** The OS from client hints, when they name one we know. */
function osFromHints(data: UaData | undefined): DeviceOs | undefined {
  switch (data?.platform.toLowerCase()) {
    case 'android':
      return 'android';
    case 'ios':
      return 'ios';
    case 'macos':
      return 'mac';
    case 'windows':
      return 'windows';
    case 'chrome os':
    case 'chromeos':
      return 'chromeos';
    case 'linux':
      return 'linux';
    default:
      return undefined;
  }
}

/** The browser from client hints' brands; the generic "Chromium" and the GREASE entries name nothing. */
function browserFromHints(data: UaData | undefined): DeviceBrowser | undefined {
  const brands = (data?.brands ?? []).map((entry) => entry.brand.toLowerCase());
  if (brands.some((brand) => brand.includes('edge'))) return 'edge';
  if (brands.some((brand) => brand.startsWith('opera'))) return 'opera';
  if (brands.includes('brave')) return 'brave';
  if (brands.some((brand) => brand.includes('samsung'))) return 'samsung';
  if (brands.includes('google chrome')) return 'chrome';
  return undefined;
}

function osOf(ua: string, touch: number): DeviceOs {
  if (/Android/i.test(ua)) return 'android';
  if (/iPhone|iPad|iPod/i.test(ua)) return 'ios';
  // iPadOS 13+ asks for the desktop site and says it is a Mac; a Mac has no
  // touch screen, so more than one touch point gives it away.
  if (/Macintosh|Mac OS X/i.test(ua)) return touch > 1 ? 'ios' : 'mac';
  if (/CrOS/i.test(ua)) return 'chromeos';
  if (/Windows/i.test(ua)) return 'windows';
  if (/Linux|X11/i.test(ua)) return 'linux';
  return 'other';
}

function browserOf(ua: string, brave: boolean): DeviceBrowser {
  // Order matters: every Chromium browser also says "Chrome", and Chrome
  // and every iOS browser also say "Safari".
  if (/Firefox|FxiOS/i.test(ua)) return 'firefox';
  if (/Edg(e|A|iOS)?\//.test(ua)) return 'edge';
  if (/OPR\/|Opera/.test(ua)) return 'opera';
  if (ua.includes('SamsungBrowser')) return 'samsung';
  if (brave) return 'brave';
  if (/Chrome|CriOS|Chromium/.test(ua)) return 'chrome';
  if (ua.includes('Safari')) return 'safari';
  return 'other';
}

/** Reads the device from what the browser reports. */
export function describeDevice(hints: DeviceHints): Device {
  const os = osFromHints(hints.uaData) ?? osOf(hints.userAgent, hints.maxTouchPoints);
  return {
    shell: hints.shell,
    os,
    browser: browserFromHints(hints.uaData) ?? browserOf(hints.userAgent, hints.brave),
    mobile:
      hints.shell === 'android' ||
      hints.shell === 'ios' ||
      os === 'android' ||
      os === 'ios' ||
      hints.uaData?.mobile === true,
  };
}

/** This device. */
export function currentDevice(): Device {
  const nav = navigator as Navigator & { brave?: unknown; userAgentData?: UaData };
  return describeDevice({
    userAgent: nav.userAgent,
    uaData: nav.userAgentData,
    maxTouchPoints: nav.maxTouchPoints,
    brave: nav.brave !== undefined,
    shell: isDesktopShell() ? 'desktop' : shellPlatform(),
  });
}

/** Which store the browser extension is installed from in this browser, if any. */
export function extensionStore(device: Device): 'chrome' | 'edge' | 'firefox' | undefined {
  // The desktop app's window is a system web view (WebView2 says "Edg/"),
  // not a browser anybody installs extensions in.
  if (device.mobile || device.shell !== 'web') return undefined;
  if (device.browser === 'firefox') return 'firefox';
  // Edge has its own listing in Microsoft Edge Add-ons (since 2026-10-12).
  if (device.browser === 'edge') return 'edge';
  // Brave and Opera install from the Chrome Web Store.
  if (device.browser === 'chrome' || device.browser === 'brave' || device.browser === 'opera')
    return 'chrome';
  return undefined;
}
