import styles from './StoryGround.module.css';

/**
 * The stories' forest ground alone: what a first visit sees while the story
 * chunk arrives, so the screen never flashes paper and a spinner before the
 * brand moment (onboarding v2 spec §12).
 */
export function StoryGround(): React.JSX.Element {
  return <div className={styles.ground} aria-busy="true" />;
}
