import { useEffect, useMemo, useRef, useState } from 'react';
import { accountAddress } from '@/features/auth/hiddenEmail.js';
import { useSearchParams } from 'react-router-dom';
import { me as meApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { describeDevice } from '@/lib/deviceName.js';
import { useAuth } from './session.js';
import { CONNECT_MESSAGES } from './connectMessages.js';
import { extensionRedirectUrl, readExtensionRequest, type ExtensionRequest } from './extensionRequest.js';
import { extensionKey, sealSession, type HandedSession } from './sealSession.js';
import styles from './SignIn.module.css';

/** How long the extension gets to confirm before the page assumes it is not there. */
const REPLY_TIMEOUT_MS = 4000;

type Outcome = 'ask' | 'working' | 'done' | 'missing' | 'failed' | 'delegated' | 'cancelled';

/**
 * Where the browser extension sends the user to be connected. The user is
 * signed in here; the extension never sees a password and can be signed out
 * alone from Settings. Two ways, chosen by the address:
 *
 * - Extension 0.3.0 and later open this page in the browser's own sign-in
 *   window (`identity.launchWebAuthFlow`) with a PKCE challenge and their
 *   identity redirect (extensionRequest.ts). Allowing asks the API for a
 *   one-time code and sends the window to that redirect, the desktop app's
 *   pattern: no token passes through this page.
 * - Extension 0.2.x, and browsers without that API (Firefox for Android),
 *   open it with `state` and `key`: see SealedConnect.
 */
export function ConnectExtension(): React.JSX.Element {
  const [params] = useSearchParams();
  const request = useMemo(() => readExtensionRequest(params), [params]);
  if (request === undefined) return <SealedConnect />;
  return <CodeConnect request={request} />;
}

type CodeOutcome = 'ask' | 'working' | 'done' | 'failed' | 'offline' | 'delegated' | 'cancelled';

/**
 * The one-time-code connect. The address was checked before anything is
 * offered: a request that is not exactly an extension's gets an explanation
 * and no redirect, ever, and the API checks the address against the
 * published extension's before a code exists.
 */
function CodeConnect({ request }: { request: ExtensionRequest | 'invalid' }): React.JSX.Element {
  const user = useAuth((s) => s.user);
  const [outcome, setOutcome] = useState<CodeOutcome>('ask');

  const leave = (answer: Record<string, string>): boolean => {
    const target = request === 'invalid' ? undefined : extensionRedirectUrl(request, answer);
    if (target === undefined) return false;
    // A navigation the browser stops and hands to the extension.
    window.location.assign(target);
    return true;
  };

  const allow = async (): Promise<void> => {
    if (request === 'invalid') return;
    setOutcome('working');
    try {
      const { code } = await meApi.createExtensionCode({
        codeChallenge: request.codeChallenge,
        codeChallengeMethod: 'S256',
        redirectUri: request.redirectUri,
      });
      setOutcome(leave({ code }) ? 'done' : 'failed');
    } catch (cause: unknown) {
      if (isApiError(cause) && cause.code === 'delegated_session') setOutcome('delegated');
      else if (isApiError(cause, 'offline')) setOutcome('offline');
      else setOutcome('failed');
    }
  };

  const cancel = (): void => {
    // The extension is waiting on its window; telling it no lets it stop.
    leave({ error: 'access_denied' });
    setOutcome('cancelled');
  };

  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('app.name')}</h1>
      </div>
      <div className={styles.form}>
        <div className={styles.formTitle}>{t('connect.title')}</div>
        {request === 'invalid' && (
          <p className={styles.error} role="alert">
            {t('connect.invalid')}
          </p>
        )}
        {request !== 'invalid' && (outcome === 'ask' || outcome === 'working') && (
          <>
            <p className={styles.lead}>
              {t('connect.lead', { email: user === null ? '' : accountAddress(user) })}
            </p>
            <button
              type="button"
              className={styles.submit}
              disabled={outcome === 'working'}
              onClick={() => {
                void allow();
              }}
            >
              {outcome === 'working' ? t('connect.working') : t('connect.allow')}
            </button>
            <button
              type="button"
              className={styles.textLink}
              disabled={outcome === 'working'}
              onClick={cancel}
            >
              {t('connect.cancel')}
            </button>
          </>
        )}
        {outcome === 'done' && (
          <p className={styles.success} role="status">
            {t('connect.done')}
          </p>
        )}
        {outcome === 'failed' && (
          <p className={styles.error} role="alert">
            {t('connect.failed')}
          </p>
        )}
        {outcome === 'offline' && (
          <p className={styles.error} role="alert">
            {t('connect.offline')}
          </p>
        )}
        {outcome === 'delegated' && (
          <p className={styles.error} role="alert">
            {t('connect.delegated')}
          </p>
        )}
        {outcome === 'cancelled' && (
          <p className={styles.lead} role="status">
            {t('connect.cancelled')}
          </p>
        )}
      </div>
    </main>
  );
}

/**
 * The sealed handoff, for extension 0.2.x and for browsers without
 * `identity.launchWebAuthFlow` (Firefox for Android), which 0.3.0 still
 * falls back to there. Allowing opens a session of the extension's own
 * through the API and hands it over with window.postMessage, sealed to the
 * public key the extension put in the address (sealSession.ts), so no other
 * script or extension on the page can read it. Remove it once 0.2.x is gone
 * from the stores and every browser the extension supports has the
 * identity API.
 */
function SealedConnect(): React.JSX.Element {
  const [params] = useSearchParams();
  // Echoed back so the extension can match the reply to its own request.
  const state = params.get('state') ?? '';
  // The extension's public key. Extension 0.1.x opens this page without one.
  const key = params.get('key');
  const user = useAuth((s) => s.user);
  const [outcome, setOutcome] = useState<Outcome>('ask');
  const [present, setPresent] = useState(false);
  const replyTimer = useRef<number | undefined>(undefined);

  useEffect(() => {
    const onMessage = (event: MessageEvent<{ type?: string } | null>): void => {
      if (event.source !== window || event.origin !== window.location.origin) return;
      const type = event.data?.type;
      if (type === CONNECT_MESSAGES.ready) setPresent(true);
      if (type === CONNECT_MESSAGES.connected) {
        if (replyTimer.current !== undefined) window.clearTimeout(replyTimer.current);
        setOutcome('done');
      }
    };
    window.addEventListener('message', onMessage);
    // The content script announced itself before this page mounted; ask again.
    window.postMessage({ type: CONNECT_MESSAGES.ping }, window.location.origin);
    return () => {
      window.removeEventListener('message', onMessage);
      if (replyTimer.current !== undefined) window.clearTimeout(replyTimer.current);
    };
  }, []);

  const allow = async (): Promise<void> => {
    setOutcome('working');
    try {
      // The key is read before a session is opened: an address with a key
      // that is not one gets nothing minted that nobody could receive.
      const peer = key === null ? undefined : await extensionKey(key);
      if (key !== null && (peer === undefined || state === '')) {
        setOutcome('failed');
        return;
      }
      const session = await meApi.connectClient({
        platform: 'extension',
        deviceName: describeDevice(),
      });
      const handed: HandedSession = {
        accessToken: session.accessToken,
        expiresIn: session.expiresIn,
        refreshToken: session.refreshToken ?? '',
        user: { id: session.user.id, email: session.user.email, displayName: session.user.displayName },
      };
      if (peer !== undefined) {
        const sealed = await sealSession(handed, state, peer);
        window.postMessage({ type: CONNECT_MESSAGES.sealed, state, sealed }, window.location.origin);
      } else {
        // Extension 0.1.x, for one release: see CONNECT_MESSAGES.legacySession.
        window.postMessage(
          { type: CONNECT_MESSAGES.legacySession, state, session: handed },
          window.location.origin,
        );
      }
      replyTimer.current = window.setTimeout(() => {
        setOutcome('missing');
      }, REPLY_TIMEOUT_MS);
    } catch (cause: unknown) {
      // A session that was itself handed to a program cannot hand out another.
      setOutcome(cause instanceof ApiError && cause.code === 'delegated_session' ? 'delegated' : 'failed');
    }
  };

  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('app.name')}</h1>
      </div>
      <div className={styles.form}>
        <div className={styles.formTitle}>{t('connect.title')}</div>
        {(outcome === 'ask' || outcome === 'working') && (
          <>
            <p className={styles.lead}>
              {t('connect.lead', { email: user === null ? '' : accountAddress(user) })}
            </p>
            {!present && outcome === 'ask' && (
              <p className={styles.note} role="note">
                {t('connect.missing')}
              </p>
            )}
            {/* Nothing is listening, so there is nobody to hand a session
                to. Allowing anyway used to mint one for no one: a live
                session on the account that no extension holds, which then
                reads everywhere else as "the extension is connected". The
                page already knows; now it waits. */}
            <button
              type="button"
              className={styles.submit}
              disabled={outcome === 'working' || !present}
              onClick={() => {
                void allow();
              }}
            >
              {outcome === 'working' ? t('connect.working') : t('connect.allow')}
            </button>
            <button
              type="button"
              className={styles.textLink}
              onClick={() => {
                setOutcome('cancelled');
              }}
            >
              {t('connect.cancel')}
            </button>
          </>
        )}
        {outcome === 'done' && (
          <p className={styles.success} role="status">
            {t('connect.done')}
          </p>
        )}
        {outcome === 'missing' && (
          <p className={styles.error} role="alert">
            {t('connect.missing')}
          </p>
        )}
        {outcome === 'failed' && (
          <p className={styles.error} role="alert">
            {t('connect.failed')}
          </p>
        )}
        {outcome === 'delegated' && (
          <p className={styles.error} role="alert">
            {t('connect.delegated')}
          </p>
        )}
        {outcome === 'cancelled' && (
          <p className={styles.lead} role="status">
            {t('connect.cancelled')}
          </p>
        )}
      </div>
    </main>
  );
}
