import { useEffect, useState } from 'react';
import { accountAddress } from '@/features/auth/hiddenEmail.js';
import { useSearchParams } from 'react-router-dom';
import { connections } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import type { ApiAuthorizationRequest } from '@/api/types.js';
import { Icon } from '@/components/ui/Icon.js';
import { Skeleton } from '@/components/ui/Skeleton.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { useAuth } from '@/features/auth/session.js';
import authStyles from '@/features/auth/SignIn.module.css';
import { familyLabel, selfDeclared } from './family.js';
import { assistantRedirect } from './redirect.js';
import styles from './ConnectAssistant.module.css';

/** The shape /oauth/authorize mints request ids in; anything else is not one of ours. */
const REQUEST_ID = /^[A-Za-z0-9_-]{1,64}$/u;

type Scope = ApiAuthorizationRequest['scopes'][number];

/** What each scope lets the assistant do, in the words the learner reads. */
const SCOPE_LABEL: Record<Scope, MessageKey> = {
  'words:read': 'connectAi.scopeRead',
  'words:write': 'connectAi.scopeWrite',
  'practice:write': 'connectAi.scopePractice',
  'words:delete': 'connectAi.scopeDelete',
};
/** Scopes in a fixed order, whatever order the server sent them in. */
const SCOPE_ORDER: readonly Scope[] = ['words:read', 'words:write', 'practice:write', 'words:delete'];

/** What no scope grants, said out loud so nobody has to infer it. */
const NEVER: readonly MessageKey[] = [
  'connectAi.neverPassword',
  'connectAi.neverEmail',
  'connectAi.neverDelete',
  'connectAi.neverPay',
];

type State =
  | { kind: 'loading' }
  | { kind: 'ask'; request: ApiAuthorizationRequest; busy: boolean; error?: MessageKey }
  | { kind: 'leaving'; host: string }
  | { kind: 'gone'; app: string }
  | { kind: 'unsafe' }
  | { kind: 'failed'; offline: boolean };

/** The app the learner came from, for "start again from …". */
function appName(request?: ApiAuthorizationRequest): string {
  if (request?.knownClient === 'chatgpt') return t('connectAi.appChatgpt');
  if (request?.knownClient === 'claude') return t('connectAi.appClaude');
  return t('connectAi.appOther');
}

/**
 * The consent screen ChatGPT or Claude sends a learner to when it asks to
 * connect. The API checked the client, its redirect address, PKCE and the
 * resource before creating the request; this screen shows what it is asking
 * for, takes the learner's answer and sends the browser back with it.
 *
 * The headline names the verified family (ChatGPT, Claude, or an app on
 * this computer), never the name the client chose for itself, which anybody
 * can set to "ChatGPT"; that name is only secondary text. The verified host
 * the answer goes to is the prominent fact. The address the browser is sent
 * to comes from the server and is checked again here before it is followed.
 *
 * The request is bound to the browser that opened /oauth/authorize by a
 * cookie the API set; the client sends credentials, so a link opened in
 * any other browser reads as expired and says to start again here.
 */
export function ConnectAssistant(): React.JSX.Element {
  const [params] = useSearchParams();
  const id = params.get('request') ?? '';
  const email = useAuth((s) => (s.user === null ? '' : accountAddress(s.user)));
  const validId = REQUEST_ID.test(id);
  const [fetched, setState] = useState<State>({ kind: 'loading' });
  // An id that is not one of ours is never sent to the server.
  const state: State = validId ? fetched : { kind: 'gone', app: appName() };

  useEffect(() => {
    if (!validId) return;
    let live = true;
    connections
      .request(id)
      .then((request) => {
        if (live) setState({ kind: 'ask', request, busy: false });
      })
      .catch((cause: unknown) => {
        if (!live) return;
        if (isApiError(cause, 'notFound')) setState({ kind: 'gone', app: appName() });
        else setState({ kind: 'failed', offline: isApiError(cause, 'offline') });
      });
    return () => {
      live = false;
    };
  }, [id, validId]);

  const decide = (request: ApiAuthorizationRequest, allow: boolean): void => {
    setState({ kind: 'ask', request, busy: true });
    connections
      .decide(request.id, allow)
      .then(({ redirectTo }) => {
        const target = assistantRedirect(redirectTo, request.redirectHost);
        if (target === undefined) {
          setState({ kind: 'unsafe' });
          return;
        }
        setState({ kind: 'leaving', host: request.redirectHost });
        // A navigation, not a form post: the security policy's form-action stays 'self'.
        window.location.assign(target.href);
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'notFound')) {
          setState({ kind: 'gone', app: appName(request) });
          return;
        }
        setState({
          kind: 'ask',
          request,
          busy: false,
          error: isApiError(cause, 'offline')
            ? 'connectAi.offline'
            : isApiError(cause, 'forbidden')
              ? 'connectAi.needsApp'
              : 'connectAi.failed',
        });
      });
  };

  return (
    <main className={authStyles.wrap}>
      <div className={authStyles.brand}>
        <div className={authStyles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <p className={authStyles.name}>{t('app.name')}</p>
      </div>
      <div className={authStyles.form}>
        {state.kind === 'loading' && (
          <>
            <span className="sr-only" role="status">
              {t('state.loading')}
            </span>
            <Skeleton lines={5} />
          </>
        )}
        {state.kind === 'ask' && (
          <Consent
            request={state.request}
            email={email}
            busy={state.busy}
            error={state.error}
            onDecide={(allow) => {
              decide(state.request, allow);
            }}
          />
        )}
        {state.kind === 'leaving' && (
          <p className={authStyles.success} role="status">
            {t('connectAi.leaving', { host: state.host })}
          </p>
        )}
        {state.kind === 'gone' && (
          <>
            <h1 className={styles.title}>{t('connectAi.goneTitle')}</h1>
            <p className={authStyles.lead} role="alert">
              {t('connectAi.gone', { app: state.app })}
            </p>
          </>
        )}
        {state.kind === 'unsafe' && (
          <p className={authStyles.error} role="alert">
            {t('connectAi.unsafe')}
          </p>
        )}
        {state.kind === 'failed' && (
          <p className={authStyles.error} role="alert">
            {state.offline ? t('connectAi.offline') : t('connectAi.failed')}
          </p>
        )}
      </div>
    </main>
  );
}

function Consent({
  request,
  email,
  busy,
  error,
  onDecide,
}: {
  request: ApiAuthorizationRequest;
  email: string;
  busy: boolean;
  error: MessageKey | undefined;
  onDecide: (allow: boolean) => void;
}): React.JSX.Element {
  const scopes = SCOPE_ORDER.filter((scope) => request.scopes.includes(scope));
  const calls = selfDeclared(request.clientName, request.knownClient);
  return (
    <>
      <h1 className={styles.title}>{t('connectAi.title', { client: familyLabel(request.knownClient) })}</h1>
      {calls !== undefined && (
        <p className={styles.selfDeclared} dir="auto">
          {t('connectAi.selfDeclared', { name: calls })}
        </p>
      )}
      {request.knownClient !== 'chatgpt' && request.knownClient !== 'claude' && (
        <p className={styles.warning} role="note">
          {t('connectAi.localWarning')}
        </p>
      )}
      <div className={styles.host}>
        <Icon name="lock" size={18} weight={2} />
        <span>{t('connectAi.host', { host: request.redirectHost })}</span>
      </div>
      <p className={styles.hostNote}>{t('connectAi.hostNote')}</p>

      <section className={styles.card} aria-labelledby="connect-can">
        <h2 id="connect-can" className={styles.cardTitle}>
          {t('connectAi.canTitle')}
        </h2>
        <ul className={styles.list}>
          {scopes.map((scope) => (
            <li key={scope} className={styles.item}>
              <span className={styles.yes} aria-hidden="true">
                <Icon name="check" size={16} weight={2.4} />
              </span>
              {t(SCOPE_LABEL[scope])}
            </li>
          ))}
        </ul>
      </section>
      <section className={styles.card} aria-labelledby="connect-cannot">
        <h2 id="connect-cannot" className={styles.cardTitle}>
          {t('connectAi.cannotTitle')}
        </h2>
        <ul className={styles.list}>
          {NEVER.map((key) => (
            <li key={key} className={styles.item}>
              <span className={styles.no} aria-hidden="true">
                <Icon name="close" size={16} weight={2.4} />
              </span>
              {t(key)}
            </li>
          ))}
        </ul>
      </section>

      <p className={authStyles.lead}>{t('connectAi.account', { email })}</p>
      {error !== undefined && (
        <p className={authStyles.error} role="alert">
          {t(error)}
        </p>
      )}
      <button
        type="button"
        className={authStyles.submit}
        disabled={busy}
        onClick={() => {
          onDecide(true);
        }}
      >
        {busy ? t('connectAi.working') : t('connectAi.allow')}
      </button>
      <button
        type="button"
        className={authStyles.textLink}
        disabled={busy}
        onClick={() => {
          onDecide(false);
        }}
      >
        {t('connectAi.cancel')}
      </button>
      <p className={authStyles.note}>{t('connectAi.revokeNote')}</p>
    </>
  );
}
