/**
 * Where the update toast sits so that it never covers a place to type.
 *
 * The toast floats above the tab bar. On Lex the composer is pinned there
 * too, and the toast hid it: a learner tapped the toast thinking it was the
 * box, focus fell to the page, and what they typed went to the shortcuts
 * (N opened Add a word). A screen marks what must stay clear with
 * `data-keep-clear`, and a focused text field always counts too; the toast
 * then rises above all of them, or goes to the top of the screen when there
 * is no room left below.
 *
 * Kept as plain arithmetic on rectangles so it can be tested without a
 * browser that lays anything out.
 */

/** A rectangle on the screen, in CSS pixels from the viewport's top left. */
export interface Box {
  readonly top: number;
  readonly bottom: number;
  readonly left: number;
  readonly right: number;
}

/** Where to put the toast: its distance from the viewport's bottom, or the top. */
export type Placement = { readonly edge: 'bottom'; readonly offset: number } | { readonly edge: 'top' };

/** Space between the toast and what it steps out of the way of. */
export const KEEP_CLEAR_GAP = 8;

/** What a screen marks as never to be covered, such as a pinned composer. */
export const KEEP_CLEAR_SELECTOR = '[data-keep-clear]';

function overlaps(a: Box, b: Box, gap: number): boolean {
  return a.left < b.right && b.left < a.right && a.top < b.bottom + gap && b.top - gap < a.bottom;
}

/**
 * Places a toast of `toast`'s size, whose own spot is `offset` pixels above
 * the bottom of a `viewport`-tall screen, clear of every box in `keepClear`.
 * It only ever moves up, by as little as it takes; when it would leave the
 * top of the screen it goes to the top instead (`top` is the room the top
 * edge needs: the safe area and a little more).
 */
export function placeToast(
  viewport: number,
  offset: number,
  toast: Box,
  keepClear: readonly Box[],
  top = 0,
  gap = KEEP_CLEAR_GAP,
): Placement {
  const height = toast.bottom - toast.top;
  let lift = offset;
  // Each step only rises, past at least one box, so it ends within one pass
  // per box.
  for (let step = 0; step <= keepClear.length; step += 1) {
    const at: Box = { ...toast, top: viewport - lift - height, bottom: viewport - lift };
    const hit = keepClear.filter((box) => overlaps(at, box, gap));
    if (hit.length === 0) break;
    lift = Math.max(...hit.map((box) => viewport - box.top + gap));
  }
  if (viewport - lift - height < top) return { edge: 'top' };
  return { edge: 'bottom', offset: lift };
}
