import { Icon, type IconName } from './Icon.js';
import { cx } from '@/lib/cx.js';
import styles from './EmptyState.module.css';

/**
 * A screen, or a section of one, with nothing in it yet.
 *
 * There is more than one kind of nothing and they want different words: a
 * notebook nobody has written in is not a filter that matched nothing, and
 * neither is a day with no reviews left. What they share is the shape --
 * a small mark, a heading somebody can read at a glance, one sentence, and
 * the most useful thing to do next -- so that shape lives here instead of
 * being drawn slightly differently on every screen.
 *
 * The mark is an icon from the set by default. A screen with something
 * better to draw passes its own; `Progress` draws the five boxes, empty,
 * because the shape of what is coming is more use than a symbol for it.
 */
export function EmptyState({
  icon,
  mark,
  tone = 'accent',
  title,
  body,
  actions,
  compact = false,
  middle = false,
  heading = 'h2',
  titleRef,
  kicker,
}: {
  icon?: IconName;
  /** Drawn instead of an icon, for a screen whose emptiness has a shape. */
  mark?: React.ReactNode;
  tone?: 'accent' | 'quiet';
  title: string;
  /** Left out where what follows already says it (a Pro gate's offer card). */
  body?: string | undefined;
  actions?: React.ReactNode;
  /** For a section inside a screen rather than the whole of one. */
  compact?: boolean;
  /** Takes the height and centres in it, when it is the whole screen. */
  middle?: boolean;
  /** h1 when it is the whole screen's heading (a form's outcome), so focus can land on it. */
  heading?: 'h1' | 'h2';
  /** For moving focus to the heading when the state appears (WCAG 4.1.3). */
  titleRef?: React.Ref<HTMLHeadingElement> | undefined;
  /** A small line above the heading naming what it is about (a form's title). */
  kicker?: string | undefined;
}): React.JSX.Element {
  const Heading = heading;
  return (
    <div className={cx(styles.empty, compact && styles.compact, middle && styles.middle)}>
      {mark ?? (
        <span className={cx(styles.mark, tone === 'quiet' && styles.markQuiet)} aria-hidden="true">
          <Icon name={icon ?? 'notebook'} size={compact ? 20 : 26} weight={1.8} />
        </span>
      )}
      {kicker !== undefined && (
        <p className={styles.kicker} dir="auto">
          {kicker}
        </p>
      )}
      <Heading
        ref={titleRef}
        className={cx(styles.title, compact && styles.titleCompact)}
        {...(titleRef === undefined ? {} : { tabIndex: -1 })}
      >
        {title}
      </Heading>
      {body !== undefined && <p className={styles.body}>{body}</p>}
      {actions !== undefined && <div className={styles.actions}>{actions}</div>}
    </div>
  );
}
