/**
 * Where a visit came from, carried to the sign-up it leads to (growth plan,
 * 2026-10-12). A link may carry `?ref=` (or `utm_source`): a short source
 * word such as `reddit` or `yt`, or a friend's invitation, `inv-<code>`,
 * which the landing site's `/r/<code>` redirect adds. It is kept in
 * `platform.prefs` (one of the few things allowed there: it must survive the
 * sign-up and Google's redirect), sent once after signing in, and then
 * forgotten. It is a word, never an address, an id or a click id, and it is
 * never sent anywhere but our own API. A visit with no ref falls back to the
 * referring site's host, turned into a word (`source.ts`, 2026-10-20).
 *
 * Sign-up sources, 2026-10-21 (96% of sign-ups had none): a `utm_source`
 * that is a host (`chatgpt.com`) is read as that site; a visit from
 * lexpad.app itself, or one that opened the desktop app's or the
 * extension's sign-in, is held as a weak word that any real source
 * replaces; the Android shell asks Google Play's install referrer once; and
 * a new account with nothing held at all is sent a fallback word for how it
 * got here (`direct` on the web, `play`, `appstore`, `desktop-app`), so
 * "no source recorded" means only an app too old to say.
 */
import { me } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { newIdempotencyKey } from '@/api/client.js';
import { platform } from '@/lib/platform/index.js';
import { sourceFromInstallReferrer, sourceFromParam, sourceFromReferrer } from './source.js';

/** The prefs key; documented in apps/web/CLAUDE.md beside the others. */
export const REF_KEY = 'lexpad.ref';

/** What starts an invitation ref; the rest is the friend's code. */
export const INVITE_PREFIX = 'inv-';

/**
 * How long a remembered ref still counts. A visit weeks before the sign-up
 * did not bring it about; the server also ignores accounts past their first
 * hours, so this only keeps stale words from being sent at all.
 */
export const REF_KEEP_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

// The shapes the server accepts (domain/referral in the API): a code is
// eight characters without look-alikes; a source is a short lower-case word.
const CODE = /^[a-hjkmnp-z2-9]{8}$/;
const SOURCE = /^[a-z0-9][a-z0-9_-]{0,31}$/;

/** A ref as the server would read it, or undefined when it is not one. */
export function cleanRef(raw: string | null | undefined): string | undefined {
  if (typeof raw !== 'string') return undefined;
  const value = raw.trim().toLowerCase();
  if (value.startsWith(INVITE_PREFIX)) {
    return CODE.test(value.slice(INVITE_PREFIX.length)) ? value : undefined;
  }
  return SOURCE.test(value) ? value : undefined;
}

/**
 * Words that say only which door a visit came through, never where the
 * person found us: any other source replaces them, and they replace
 * nothing. `site` is lexpad.app with no source of its own (typed, a
 * bookmark, or a link that sent no referrer); `desktop-app` and `extension`
 * are the sign-ins those two open in the browser.
 */
export const WEAK_SOURCES: ReadonlySet<string> = new Set(['site', 'desktop-app', 'extension']);

/** Whether a ref is a friend's invitation. */
export function isInvite(ref: string | undefined): boolean {
  return ref?.startsWith(INVITE_PREFIX) === true;
}

interface Stored {
  ref: string;
  at: number;
}

function read(now: number): Stored | undefined {
  const raw = platform.prefs.get(REF_KEY);
  if (raw === null) return undefined;
  try {
    const value = JSON.parse(raw) as Partial<Stored>;
    const ref = cleanRef(value.ref);
    if (ref === undefined || typeof value.at !== 'number' || now - value.at > REF_KEEP_DAYS * DAY_MS) {
      platform.prefs.remove(REF_KEY);
      return undefined;
    }
    return { ref, at: value.at };
  } catch {
    platform.prefs.remove(REF_KEY);
    return undefined;
  }
}

/** The ref this device is holding for a sign-up, if any. */
export function pendingRef(now: number = Date.now()): string | undefined {
  return read(now)?.ref;
}

/**
 * Pages a visit reaches on its way through something we started: back from
 * Google's sign-in, a link in one of our e-mails (opened from web mail, whose
 * redirect looks like a Google or Outlook visit), a sign-in for the desktop
 * app or the extension. Their referrer says nothing about where the person
 * first came from, so it is not read there.
 */
const NO_REFERRER_PATHS = [
  '/auth/google/callback',
  '/verify',
  '/forgot',
  '/reset-password',
  '/unsubscribe',
  '/connect-desktop',
  '/connect-extension',
  '/report-ai',
];

/** Where the visit is and what sent it there; read from `document` in main.tsx. */
export interface Visit {
  /** `document.referrer`; only its host is read. */
  referrer?: string;
  /** `location.pathname`. */
  path?: string;
}

function referrerCounts(path: string): boolean {
  const clean = path.replace(/\/+$/, '') || '/';
  return !NO_REFERRER_PATHS.some((p) => clean === p || clean.startsWith(`${p}/`));
}

/** The landing site's own hosts: a visit from there with no `?ref=` is `site`. */
const LANDING_HOSTS = new Set(['lexpad.app', 'www.lexpad.app']);

/** Sign-in pages another Lexpad app opens in the browser, and the weak word for each. */
const DOOR_PATHS: readonly (readonly [string, string])[] = [
  ['/connect-desktop', 'desktop-app'],
  ['/connect-extension', 'extension'],
];

function pathIs(path: string, prefix: string): boolean {
  const clean = path.replace(/\/+$/, '') || '/';
  return clean === prefix || clean.startsWith(`${prefix}/`);
}

function weakSource(visit: Visit): string | undefined {
  const path = visit.path ?? '/';
  for (const [prefix, word] of DOOR_PATHS) if (pathIs(path, prefix)) return word;
  if (!referrerCounts(path) || typeof visit.referrer !== 'string') return undefined;
  try {
    const url = new URL(visit.referrer);
    return LANDING_HOSTS.has(url.hostname.toLowerCase()) ? 'site' : undefined;
  } catch {
    return undefined;
  }
}

function isWeak(ref: string): boolean {
  return WEAK_SOURCES.has(ref);
}

/** Holds a ref unless a stronger one is already held (first touch, see noteRef). */
function hold(ref: string, now: number): void {
  const held = read(now);
  if (held !== undefined) {
    if (isWeak(ref)) return;
    if (!isWeak(held.ref) && (isInvite(held.ref) || !isInvite(ref))) return;
  }
  platform.prefs.set(REF_KEY, JSON.stringify({ ref, at: now }));
}

/**
 * Notes the ref of the address the app was opened at, or, with none, the
 * word for the site that sent the visit here. First touch: a source
 * already held stays, except that a friend's invitation replaces a plain
 * source, because following a friend's link is the more deliberate act, and
 * any source replaces a weak one (`WEAK_SOURCES`). A second invitation never
 * replaces the first.
 */
export function noteRef(search: string, now: number = Date.now(), visit: Visit = {}): void {
  let params: URLSearchParams;
  try {
    params = new URLSearchParams(search);
  } catch {
    return;
  }
  const ref =
    cleanRef(params.get('ref')) ??
    cleanRef(sourceFromParam(params.get('ref') ?? params.get('utm_source'))) ??
    (referrerCounts(visit.path ?? '/') ? cleanRef(sourceFromReferrer(visit.referrer)) : undefined) ??
    weakSource(visit);
  if (ref === undefined) return;
  hold(ref, now);
}

/** Set once Google Play's install referrer was asked for on this install. */
export const INSTALL_REF_KEY = 'lexpad.install-ref';

let installRead: Promise<void> | undefined;

/**
 * Asks Google Play once per install where the app was installed from (the
 * Android shell only; elsewhere `platform.installReferrer` is absent) and
 * holds the word like a `?ref=`. Play answers for 90 days after the install;
 * an older shell without the plugin, or Play not answering, leaves nothing
 * held and is asked again on the next start. `sendRef` waits for it.
 */
export function noteInstallRef(now: number = Date.now()): Promise<void> {
  const ask = platform.installReferrer;
  if (ask === undefined || platform.prefs.get(INSTALL_REF_KEY) !== null) return Promise.resolve();
  installRead ??= ask()
    .then((raw) => {
      if (raw === undefined) return;
      platform.prefs.set(INSTALL_REF_KEY, '1');
      const ref = cleanRef(sourceFromInstallReferrer(raw));
      if (ref !== undefined) hold(ref, now);
    })
    .catch(() => undefined)
    .finally(() => {
      installRead = undefined;
    });
  return installRead;
}

/**
 * The word a new account is sent when this device holds nothing: the door
 * it came through, with where the person found us unknown. The web's is
 * `direct` (typed, a bookmark, an app that sends no referrer, or a source
 * older than REF_KEEP_DAYS).
 */
export function fallbackSource(shell: 'web' | 'ios' | 'android' | 'desktop'): string {
  switch (shell) {
    case 'android':
      return 'play';
    case 'ios':
      return 'appstore';
    case 'desktop':
      return 'desktop-app';
    default:
      return 'direct';
  }
}

/** Set to the account id once its source was sent from this device. */
export const REF_SENT_KEY = 'lexpad.ref-sent';

/**
 * How young an account must be for the fallback word to be sent. The server
 * keeps a source only for an account in its first day either way
 * (app/referral defaultSourceWindow); this keeps older accounts from asking.
 */
export const FALLBACK_HOURS = 24;

const HOUR_MS = 60 * 60 * 1000;

/** The account that just signed in, as sendRef needs it. */
export interface NewAccount {
  id: string;
  createdAt: string;
}

function isNew(account: NewAccount | undefined, now: number): account is NewAccount {
  if (account === undefined) return false;
  const created = Date.parse(account.createdAt);
  return Number.isFinite(created) && now - created <= FALLBACK_HOURS * HOUR_MS;
}

let sending: Promise<void> | undefined;

/**
 * Sends the held ref for the account that just signed in, once, and
 * forgets it. The server keeps it only for an account in its first hours,
 * so an older account signing in on this device changes nothing. With
 * nothing held, an account in its first FALLBACK_HOURS is sent the
 * fallback word for this platform, once per account on this device. Offline
 * or a server error keeps it for the next start; any answer from the server
 * (204, or a refusal) ends it.
 */
export function sendRef(account?: NewAccount, now: number = Date.now()): Promise<void> {
  sending ??= (async () => {
    await noteInstallRef(now);
    const held = pendingRef(now);
    const fresh = isNew(account, now) && platform.prefs.get(REF_SENT_KEY) !== account.id;
    const ref = held ?? (fresh ? fallbackSource(platform.env.platform) : undefined);
    if (ref === undefined) return;
    const done = (): void => {
      platform.prefs.remove(REF_KEY);
      if (account !== undefined) platform.prefs.set(REF_SENT_KEY, account.id);
    };
    try {
      await me.attributeSignup({ ref }, newIdempotencyKey());
      done();
    } catch (error) {
      if (isApiError(error, 'offline') || isApiError(error, 'server') || isApiError(error, 'unauthenticated'))
        return;
      done();
    }
  })().finally(() => {
    sending = undefined;
  });
  return sending;
}
