import { useEffect, useRef, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Spinner } from '@/components/ui/Spinner.js';
import { t } from '@/i18n/index.js';
import { consumeOAuthState } from './oauthState.js';
import { GOOGLE_POPUP_CHANNEL, GOOGLE_POPUP_STATE_PREFIX } from './providerProof.js';
import { useAuth } from './session.js';
import { takeReturnPath } from './returnPath.js';
import styles from './SignIn.module.css';

/**
 * Where Google returns the user. The code goes straight to the backend for
 * exchange; this component checks the state nonce, reads the code off the URL
 * and waits.
 *
 * A popup opened by a signed-in screen (providerProof.ts) is answered
 * differently: the code is handed back to that screen over a same-origin
 * BroadcastChannel, where the state is checked against the one it made, and
 * the popup closes. Nothing is signed in here.
 */
export function GoogleCallback(): React.JSX.Element {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const { signInWithGoogle } = useAuth();
  const started = useRef(false);
  // A popup opened by a signed-in screen only hands its code back.
  const [handedBack] = useState(() => params.get('state')?.startsWith(GOOGLE_POPUP_STATE_PREFIX) === true);

  useEffect(() => {
    if (started.current) return;
    started.current = true;
    const state = params.get('state');
    const code = params.get('code');
    if (handedBack) {
      const channel = new BroadcastChannel(GOOGLE_POPUP_CHANNEL);
      channel.postMessage({ state, code: code ?? '' });
      channel.close();
      window.close();
      return;
    }
    // A code that did not come back with this browser's own state is not ours to use.
    if (code === null || !consumeOAuthState(state)) {
      void navigate('/auth', { replace: true });
      return;
    }
    void signInWithGoogle({ code }).then(() => {
      // An account in its deletion grace: the choice is on the sign-in
      // page, and the return path waits for whichever account comes of it.
      if (useAuth.getState().pendingDeletion !== null) {
        void navigate('/auth', { replace: true });
        return;
      }
      void navigate(takeReturnPath() ?? '/', { replace: true });
    });
  }, [params, navigate, signInWithGoogle, handedBack]);

  if (handedBack) {
    // Some browsers keep a window open that Google's page isolated.
    return (
      <main className={styles.wrap}>
        <p className={styles.note} role="status">
          {t('auth.popupDone')}
        </p>
      </main>
    );
  }
  return <Spinner label={t('state.loading')} />;
}
