import { onIOS } from '@/features/billing/play.js';

/**
 * Whether this build offers Invite friends at all. Not in the iPhone app:
 * the invitation gives both people days of Pro, and App Store Review
 * Guideline 3.1.1 allows Pro to be unlocked there only through Apple's
 * in-app purchase. A reward is not a purchase, but the App Store review
 * should find nothing that reads as another way to Pro, so the row, the
 * page, Today's card and the sign-up line stay on the web, Android and
 * desktop only. The server keeps honouring a friend's link either way.
 */
export function invitesInThisApp(): boolean {
  return !onIOS();
}
