import type { IconName } from '@/components/ui/Icon.js';
import type { MessageKey } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';

/** One place the app's navigation can take you. */
export interface Tab {
  to: string;
  label: MessageKey;
  icon: IconName;
  /** Sections that belong to this tab, so it stays lit inside them. */
  also?: string[];
}

/** Watch: the desktop app's video player, after Notebook. */
const WATCH_TAB: Tab = { to: '/watch', label: 'nav.watch', icon: 'watch' };

/**
 * The five places, in order (six in the desktop app, with Watch). The bottom bar on a phone and the rail on a
 * larger screen draw the same list, so the two can never disagree about
 * where somebody can go.
 */
export const TABS: Tab[] = [
  { to: '/', label: 'nav.today', icon: 'today' },
  { to: '/notebook', label: 'nav.notebook', icon: 'notebook', also: ['/words'] },
  // The desktop app's video player (spec uiux/specs/2026-10-25-video-player.md
  // §24.3): its own files and the words met in them. Only where the core has
  // a player; the platform is decided once, before the first frame.
  ...(platform.desktop?.player !== undefined ? [WATCH_TAB] : []),
  { to: '/assistant', label: 'nav.ai', icon: 'sparkles' },
  { to: '/progress', label: 'nav.progress', icon: 'progress' },
  { to: '/settings', label: 'nav.settings', icon: 'settings' },
];

/**
 * Decks and the games, as places in the sidebar (SRS v2 access proposal 1):
 * on a larger screen the games and drills had no way in but a tile on
 * Today. They are not among the five tabs, so a phone's bottom bar never
 * changes; the sidebar shows them under Notebook while games and drills are
 * switched on. Each takes the icon of its row on Today. A game in progress
 * (`/practice/…`) belongs to the games.
 */
export const DECKS_PLACE: Tab = { to: '/decks', label: 'nav.decks', icon: 'cards' };
export const GAMES_PLACE: Tab = { to: '/games', label: 'nav.games', icon: 'grid', also: ['/practice'] };

/** Whether a tab is the one the address is in. */
export function tabMatches(tab: Tab, pathname: string): boolean {
  return tab.to === '/'
    ? pathname === '/'
    : pathname.startsWith(tab.to) || (tab.also ?? []).some((p) => pathname.startsWith(p));
}

/** Where the add button goes: the notebook, with the add sheet open. */
export const ADD_WORD_PATH = '/notebook?add=1';
