/**
 * Today's due words under each notebook's daily review limit (SRS v2), for
 * every screen that prints "to review": Today, the tab badge and the
 * sidebar. They read it the same way the session builds its plan
 * (`capDue` in @lexpad/core), so the number on Today is the number of due
 * cards the session holds.
 */
import { canPractise, capDue, type EffectiveSchedule, type SmartRisk, type Word } from '@lexpad/core';
import { loadSchedule } from '@/db/repo.js';

/** What the limits leave for today, summed over the notebooks in view. */
export interface CappedDue {
  /** Due words today asks about. */
  due: number;
  /** Due words the limits leave for tomorrow. */
  held: number;
  /** More is due than today has room for, so new words wait. */
  backlog: boolean;
}

/** Applies each notebook's limit to its own words; a notebook with none counts every due word. */
export async function cappedDue(
  notebooks: readonly { id: string }[],
  lists: readonly (readonly Word[])[],
  today: number,
): Promise<CappedDue> {
  return (await cappedDueWords(notebooks, lists, today)).capped;
}

/**
 * The same split, with the due words themselves: one list per notebook, in
 * the order the session asks them. The home-screen widgets show these.
 */
export async function cappedDueWords(
  notebooks: readonly { id: string }[],
  lists: readonly (readonly Word[])[],
  today: number,
): Promise<{ capped: CappedDue; due: string[][]; caps: number[] }> {
  const schedules = await Promise.all(notebooks.map((one) => loadSchedule(one.id)));
  const out: CappedDue = { due: 0, held: 0, backlog: false };
  const due = lists.map((words, index) => {
    const split = capDue(
      // A word with no meaning cannot be asked (`canPractise`), so it is
      // neither due today nor held for tomorrow.
      words.filter(canPractise).map((word) => ({
        wordId: word.id,
        position: word.position,
        ...(word.progress ? { progress: word.progress } : {}),
      })),
      schedules[index]?.reviewCap ?? 0,
      today,
      smartRisk(schedules[index]),
    );
    out.due += split.due.length;
    out.held += split.held;
    out.backlog = out.backlog || split.backlog;
    return split.due.map((candidate) => candidate.wordId);
  });
  return { capped: out, due, caps: schedules.map((schedule) => schedule.reviewCap) };
}

/**
 * What a capped day needs to order a Smart notebook's words by the chance of
 * remembering each today (SRS v2 phase C); nothing for Boxes.
 */
export function smartRisk(schedule: EffectiveSchedule | undefined): SmartRisk | undefined {
  return schedule?.scheduler === 'smart'
    ? { maxInterval: schedule.maxInterval, params: schedule.params }
    : undefined;
}
