/**
 * The client events of the activity contract (reports/specs/2026-10-26-activity-tracking.md
 * §3 client-only, §9, §10): kept on this device, sent in batches to
 * `POST /api/v1/events` every few minutes and as the app goes to the
 * background, never one request per event. Fire and forget: nothing is ever
 * shown, and a batch refused for what it is (4xx) is dropped; one that did not
 * get through (offline, 5xx, 429) goes back in the queue (the server counts
 * each `eventId` once).
 *
 * - **Nothing runs while the server does not take events** (`activity` in GET
 *   /config, `lib/surface.ts`): no timer, no listener, no session, no storage
 *   read or write. `startActivity` only waits for the switch, and stops all of
 *   it the moment the switch goes off. The app with the switch off is the app
 *   as it was.
 * - Every event has its own `eventId` (UUID v4, made in `signal`). An event
 *   sent more than `OFFLINE_AFTER_MS` after it happened says `offline: true`,
 *   so the server keeps its time.
 * - Batches are at most `BATCH_MAX` events and `BATCH_BYTES` of JSON (the
 *   server takes 16 KiB). As the page is hidden, one batch goes with
 *   `keepalive`; the rest waits in storage for the next run.
 * - The queue belongs to one account. It is written to that account's
 *   IndexedDB (meta `activityQueue`, with the account's id, one list per tab
 *   or window since they share the database, at most `QUEUE_MAX`, oldest
 *   dropped), so a killed app loses nothing: a list not refreshed for
 *   `STALE_TAB_MS` is a tab that is gone, and the next live tab takes it over.
 *   Where storage is refused (a private window) it lives in memory only.
 *   Stopping sends what it can with the session it still has; the switch
 *   going off keeps the rest stored for the next run, a sign-out writes
 *   nothing after it; nothing kept for one account is
 *   ever sent for another (another account's stored lists are dropped unread).
 * - Every event carries the app session (`appSession`, also sent as
 *   `X-Lexpad-App-Session` on API calls): this sender's own, in meta
 *   `activitySession`, shared by every tab, new after `SESSION_GAP_MINUTES`
 *   away. Never the nudge cards' session.
 */
import { hasSession, request, setRequestTimer } from '@/api/client.js';
import { isApiError } from '@/api/errors.js';
import { db, getMeta, setMeta } from '@/db/schema.js';
import {
  activityOn,
  onActivityGate,
  setActivitySink,
  setAppSession,
  signal,
  type QueuedEvent,
} from '@/lib/surface.js';
import { platform } from '@/lib/platform/index.js';
import { flushScreenTime, startScreenTime } from './screenTime.js';
import { flushBrowse, newBrowseSession } from './browse.js';

/** Away for longer than this, and the next visit is a new app session (§9). */
export const SESSION_GAP_MINUTES = 30;
/** How often kept events go out while the app is open (§9: "every few minutes"). */
export const FLUSH_EVERY_MS = 3 * 60_000;
/** The server's limit for one call (API section). */
export const BATCH_MAX = 50;
/** The most JSON one call carries; the server refuses a body over 16 KiB. */
export const BATCH_BYTES = 12 * 1024;
/** The most kept on this device; the oldest go first beyond it (§10). */
export const QUEUE_MAX = 500;
/** The share of finished requests whose time is reported (§9: sampled 5%). */
export const LATENCY_SAMPLE = 0.05;
/** How long a burst of events is gathered before the queue is written to storage. */
export const PERSIST_AFTER_MS = 1_000;
/** A stored list not refreshed for this long belongs to a tab that is gone (two flush rounds). */
export const STALE_TAB_MS = 2 * FLUSH_EVERY_MS;
/** Sent later than this after it happened, an event says `offline: true` and keeps its time. */
export const OFFLINE_AFTER_MS = 60_000;

export interface Kept extends QueuedEvent {
  appSession?: string;
}

/** What goes on the wire: the kept event, flagged when it is late. */
interface Sent extends Kept {
  offline?: true;
}

let queue: Kept[] = [];
let account: string | undefined;
let session: string | undefined;
let persistTimer: ReturnType<typeof setTimeout> | undefined;
let storageWorks = true;
/** Bumped by every start and stop: a write begun under an older run is not made. */
let generation = 0;
let flushing: Promise<void> | undefined;
/** Bumped by every sign-out (the sender stopped for good): a write begun before one is not made. */
let signOuts = 0;
/** This tab's (or window's) own list in the stored queue. */
let tab: string = crypto.randomUUID();

/* ------------------------------------------------------------- storage */

function persistSoon(): void {
  if (!storageWorks || account === undefined || persistTimer !== undefined) return;
  persistTimer = setTimeout(() => {
    persistTimer = undefined;
    void persist();
  }, PERSIST_AFTER_MS);
}

async function persist(): Promise<void> {
  const owner = account;
  const run = generation;
  if (!storageWorks || owner === undefined) return;
  await writeList(owner, queue, () => run === generation && account === owner);
}

/** Writes this tab's list for `owner`, if `still()` holds inside the transaction. */
async function writeList(owner: string, events: Kept[], still: () => boolean): Promise<void> {
  try {
    await db.transaction('rw', db.meta, async () => {
      // Stopped meanwhile (a sign-out that is clearing local data): no write.
      if (!still()) return;
      const kept = await getMeta('activityQueue');
      const others = kept !== null && kept.account === owner ? kept.tabs : {};
      const tabs = Object.fromEntries(Object.entries(others).filter(([id]) => id !== tab));
      if (events.length > 0) tabs[tab] = { at: Date.now(), events };
      await setMeta('activityQueue', Object.keys(tabs).length === 0 ? null : { account: owner, tabs });
    });
  } catch {
    // A private window, or storage full: the queue lives in memory only.
    storageWorks = false;
  }
}

/** A kept event read back from storage, or undefined when it is not one. */
export function readBack(value: unknown): Kept | undefined {
  if (value === null || typeof value !== 'object') return undefined;
  const event = value as Partial<Kept>;
  return typeof event.name === 'string' && typeof event.at === 'string' && typeof event.eventId === 'string'
    ? (event as Kept)
    : undefined;
}

/**
 * Takes over the lists of tabs that are gone (not refreshed for
 * `STALE_TAB_MS`), and drops what another account stored.
 */
async function adoptStale(owner: string, own: boolean): Promise<Kept[]> {
  if (!storageWorks) return [];
  const run = generation;
  try {
    return await db.transaction('rw', db.meta, async () => {
      if (run !== generation) return [];
      const kept = await getMeta('activityQueue');
      if (kept === null) return [];
      if (kept.account !== owner) {
        await setMeta('activityQueue', null);
        return [];
      }
      const now = Date.now();
      const tabs: typeof kept.tabs = {};
      const out: Kept[] = [];
      for (const [id, list] of Object.entries(kept.tabs)) {
        // This tab's own list is taken only as a run starts (what the last run kept).
        if (id === tab ? !own : now - list.at <= STALE_TAB_MS) {
          tabs[id] = list;
          continue;
        }
        for (const event of list.events) {
          const back = readBack(event);
          if (back !== undefined) out.push(back);
        }
      }
      if (Object.keys(tabs).length !== Object.keys(kept.tabs).length) {
        await setMeta('activityQueue', Object.keys(tabs).length === 0 ? null : { account: owner, tabs });
      }
      return out;
    });
  } catch {
    storageWorks = false;
    return [];
  }
}

/** Puts events back in front of the queue, each id once. */
function putBack(events: Kept[]): void {
  if (events.length === 0) return;
  const known = new Set(queue.map((event) => event.eventId));
  queue = [...events.filter((event) => !known.has(event.eventId)), ...queue].slice(-QUEUE_MAX);
  persistSoon();
}

async function takeOver(owner: string, own = false): Promise<void> {
  const back = await adoptStale(owner, own);
  if (account === owner) putBack(back);
}

/* ------------------------------------------------------------ sessions */

/** This sender's app session: new after `SESSION_GAP_MINUTES` away, shared by every tab. */
async function touchSession(now: number = Date.now()): Promise<string> {
  return db.transaction('rw', db.meta, async () => {
    const current = await getMeta('activitySession');
    const fresh = current === null || now - current.lastActiveAt > SESSION_GAP_MINUTES * 60_000;
    const id = fresh ? crypto.randomUUID().replace(/-/g, '') : current.id;
    await setMeta('activitySession', { id, lastActiveAt: now });
    return id;
  });
}

async function keepSessionAlive(now: number = Date.now()): Promise<void> {
  const run = generation;
  await db.transaction('rw', db.meta, async () => {
    if (run !== generation) return;
    const current = await getMeta('activitySession');
    if (current !== null) await setMeta('activitySession', { id: current.id, lastActiveAt: now });
  });
}

/* ------------------------------------------------------------- sending */

function keep(event: QueuedEvent): void {
  if (account === undefined) return;
  queue.push(session === undefined ? event : { ...event, appSession: session });
  if (queue.length > QUEUE_MAX) queue.splice(0, queue.length - QUEUE_MAX);
  persistSoon();
}

/** The queue cut into batches of at most `BATCH_MAX` events and `BATCH_BYTES` of JSON. */
export function batches(events: Sent[]): Sent[][] {
  const out: Sent[][] = [];
  let current: Sent[] = [];
  let bytes = 0;
  for (const event of events) {
    const size = JSON.stringify(event).length + 1;
    // One event bigger than a batch cannot be sent at all.
    if (size > BATCH_BYTES) continue;
    if (current.length >= BATCH_MAX || bytes + size > BATCH_BYTES) {
      out.push(current);
      current = [];
      bytes = 0;
    }
    current.push(event);
    bytes += size;
  }
  if (current.length > 0) out.push(current);
  return out;
}

/** Whether a failed send is worth keeping the batch for: it never reached the server, or it was busy. */
function worthKeeping(error: unknown): boolean {
  return isApiError(error, 'offline') || isApiError(error, 'server') || isApiError(error, 'tooMany');
}

/** One flush at a time; a second call waits for the first. */
export function flushEvents(keepalive = false): Promise<void> {
  flushing ??= send(keepalive).finally(() => {
    flushing = undefined;
  });
  return flushing;
}

async function send(keepalive: boolean): Promise<void> {
  const owner = account;
  // The run this send belongs to: a stop or a new start ends it, whatever the account.
  const gen = generation;
  if (!activityOn() || queue.length === 0 || owner === undefined || !hasSession()) return;
  const now = Date.now();
  const out: Sent[] = queue.splice(0).map((event) => {
    const withSession =
      event.appSession !== undefined || session === undefined ? event : { ...event, appSession: session };
    return now - Date.parse(event.at) > OFFLINE_AFTER_MS ? { ...withSession, offline: true } : withSession;
  });
  const parts = batches(out);
  // A closing page sends one batch; the others stay for the next run.
  if (keepalive && parts.length > 1) putBack(parts.slice(1).flat().map(stripOffline));
  const sending = keepalive ? parts.slice(0, 1) : parts;
  void persist();
  for (let at = 0; at < sending.length; at += 1) {
    const part = sending[at] ?? [];
    // Stopped or restarted while sending: the rest is not this run's to send.
    if (gen !== generation || account !== owner) return;
    try {
      await request('/events', {
        method: 'POST',
        body: { events: part },
        retry: false,
        // The events say their own surface; the batch claims none.
        surface: null,
        ...(keepalive ? { keepalive: true } : {}),
      });
    } catch (error) {
      if (gen !== generation || account !== owner) return;
      if (worthKeeping(error)) {
        putBack(sending.slice(at).flat().map(stripOffline));
        return;
      }
      // Refused for what it is: never sent again, never shown.
    }
  }
}

function stripOffline(event: Sent): Kept {
  const { offline: _offline, ...kept } = event;
  return kept;
}

/** The first segment of an API path, never an id: `/notebooks/01J…/words` is `notebooks`. */
export function callOf(path: string): string {
  const first = path.replace(/^\/+/, '').split(/[/?]/)[0] ?? '';
  return /^[a-z][a-z0-9-]{0,31}$/.test(first) ? first : 'other';
}

/* ------------------------------------------------------------ the run */

/**
 * Everything the sender does while the switch is on; returns the way to stop
 * it. `stop(true)` (the switch went off) keeps what was not sent stored for
 * the next run; `stop(false)` (sign-out) writes nothing more.
 */
function run(owner: string, random: () => number): (keep: boolean) => void {
  generation += 1;
  account = owner;
  queue = [];
  storageWorks = true;
  setActivitySink(keep);
  // What a run of the app that is gone (or this tab's last run) kept for this
  // account and never sent.
  void takeOver(owner, true);

  // Sampled request times; the events call itself is not measured.
  setRequestTimer((path, ms) => {
    if (path === '/events' || random() >= LATENCY_SAMPLE) return;
    signal({ name: 'client.latency', meta: { ms: Math.round(ms), route: callOf(path) } });
  });

  let opened = false;
  const begin = async (cold: boolean): Promise<void> => {
    const before = session;
    const id = await touchSession().catch(() => session);
    if (account !== owner) return;
    session = id;
    setAppSession(id);
    if (session !== before || !opened) {
      if (opened) newBrowseSession();
      opened = true;
      signal({
        name: 'app.open',
        // The cold start: from the page starting to the first screen with the sender on.
        meta: cold ? { cold: true, startMs: Math.round(performance.now()) } : { cold: false },
      });
    }
  };
  void begin(true);

  const stopScreens = startScreenTime();

  const hidden = (): void => {
    flushScreenTime();
    flushBrowse();
    signal({ name: 'app.background' });
    void keepSessionAlive().catch(() => undefined);
    void flushEvents(true);
  };
  const onVisibility = (): void => {
    if (document.visibilityState === 'hidden') hidden();
    else void begin(false);
  };
  document.addEventListener('visibilitychange', onVisibility);
  // A shell's resume, whatever the web view says about visibility.
  const offResume = platform.lifecycle.onResume(() => {
    void begin(false);
  });
  const timer = setInterval(() => {
    if (document.visibilityState === 'hidden') return;
    // A tab in use keeps the shared app session alive for the other tabs,
    // refreshes its own stored list and takes over the lists of tabs gone.
    void keepSessionAlive().catch(() => undefined);
    void persist();
    void takeOver(owner).then(() => flushEvents());
  }, FLUSH_EVERY_MS);

  return (keep: boolean) => {
    flushScreenTime();
    flushBrowse();
    // Sent with the session it still has (only while the switch is on).
    void flushEvents(true);
    // The switch going off is no reason to lose what was kept: it waits in
    // storage for the next run. A sign-out writes nothing after it.
    if (keep && storageWorks) {
      // Not after a sign-out that came meanwhile: it is clearing local data.
      const before = signOuts;
      void writeList(owner, [...queue], () => signOuts === before);
    }
    generation += 1;
    clearInterval(timer);
    clearTimeout(persistTimer);
    persistTimer = undefined;
    document.removeEventListener('visibilitychange', onVisibility);
    offResume();
    stopScreens();
    setRequestTimer(undefined);
    setActivitySink(undefined);
    setAppSession(undefined);
    queue = [];
    account = undefined;
    session = undefined;
  };
}

/**
 * The sender for one signed-in account: waits for the server's switch, runs
 * while it is on, stops the moment it goes off. Returns the way to stop it
 * (sign-out, another account).
 */
export function startActivity(owner: string, random: () => number = Math.random): () => void {
  let stop: ((keep: boolean) => void) | undefined;
  const follow = (on: boolean): void => {
    if (on && stop === undefined && account === undefined) stop = run(owner, random);
    else if (!on && stop !== undefined) {
      stop(true);
      stop = undefined;
    }
  };
  follow(activityOn());
  const offGate = onActivityGate(follow);
  return () => {
    signOuts += 1;
    offGate();
    stop?.(false);
    stop = undefined;
  };
}

/**
 * The crash screen: the app that ran the sender has just been taken down,
 * so the event is stored for the account still signed in (`owner`, from the
 * session store) and goes with its next start. Nothing for a signed-out page.
 */
export async function keepForNextStart(event: QueuedEvent, owner: string | undefined): Promise<void> {
  if (owner === undefined || !activityOn()) return;
  try {
    await db.transaction('rw', db.meta, async () => {
      const kept = await getMeta('activityQueue');
      const tabs = kept !== null && kept.account === owner ? { ...kept.tabs } : {};
      // A list of its own, stale from the start, so the next start takes it.
      tabs[`crash-${event.eventId}`] = { at: 0, events: [event] };
      await setMeta('activityQueue', { account: owner, tabs });
    });
  } catch {
    // Nowhere to keep it: it is lost, as a crash in a private window loses it.
  }
}

/** For tests. */
export function __activityQueueForTests(): readonly Kept[] {
  return queue;
}

export function __resetActivityForTests(): void {
  tab = crypto.randomUUID();
  queue = [];
  account = undefined;
  session = undefined;
  storageWorks = true;
  flushing = undefined;
  generation += 1;
  clearTimeout(persistTimer);
  persistTimer = undefined;
}
