import { useEffect, useRef, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { longDate } from '@/lib/format.js';
import { accountAddress } from './hiddenEmail.js';
import { useAuth, type PendingDeletion } from './session.js';
import styles from './PendingDeletion.module.css';

/** How the sign-in that got here proved itself, in the learner's words. */
function providerName(provider: PendingDeletion['provider']): string {
  switch (provider) {
    case 'apple':
      return t('deletion.withApple');
    case 'google':
      return t('deletion.withGoogle');
    default:
      return t('deletion.withPassword');
  }
}

/**
 * A sign-in reached an account in its thirty-day deletion grace. Nothing is
 * signed in yet: the learner restores the account, or leaves it to be erased
 * on its date and starts a new one with the same sign-in. Starting again
 * cannot be undone (the old account can no longer be restored), so it asks
 * first; restoring is reversible (it can be deleted again) and acts at once.
 */
export function PendingDeletionChoice({ pending }: { pending: PendingDeletion }): React.JSX.Element {
  const { busy, error, restoreDeletedAccount, startNewAccount, dismissPendingDeletion } = useAuth();
  const [confirming, setConfirming] = useState(false);
  const heading = useRef<HTMLHeadingElement>(null);
  useEffect(() => {
    heading.current?.focus();
  }, [confirming]);

  const date = longDate(pending.deleteOn);
  const account = accountAddress({ email: pending.email });

  return (
    <main className={styles.wrap}>
      <section className={styles.card} aria-labelledby="pending-deletion-title">
        <div className={styles.badge} aria-hidden="true">
          <Icon name="clock" size={22} weight={2} />
        </div>
        {confirming ? (
          <>
            <h1 id="pending-deletion-title" ref={heading} tabIndex={-1} className={styles.title}>
              {t('deletion.confirmTitle')}
            </h1>
            <p className={styles.body}>{t('deletion.confirmBody', { date })}</p>
            {error !== null && (
              <p className={styles.error} role="alert">
                {error}
              </p>
            )}
            <div className={styles.actions}>
              <button
                type="button"
                className={styles.primary}
                disabled={busy}
                onClick={() => {
                  void startNewAccount();
                }}
              >
                {busy ? t('deletion.working') : t('deletion.confirmStart')}
              </button>
              <button
                type="button"
                className={styles.secondary}
                disabled={busy}
                onClick={() => {
                  setConfirming(false);
                }}
              >
                {t('deletion.back')}
              </button>
            </div>
          </>
        ) : (
          <>
            <h1 id="pending-deletion-title" ref={heading} tabIndex={-1} className={styles.title}>
              {t('deletion.title')}
            </h1>
            <p className={styles.account}>{account}</p>
            <p className={styles.when}>
              <span className={styles.whenLabel}>{t('deletion.erasedOn')}</span>
              <span className={styles.whenDate}>{date}</span>
            </p>
            <p className={styles.body}>
              {pending.canRestore
                ? t('deletion.body', { provider: providerName(pending.provider) })
                : t('deletion.bodyClosed', { provider: providerName(pending.provider) })}
            </p>
            {error !== null && (
              <p className={styles.error} role="alert">
                {error}
              </p>
            )}
            <div className={styles.actions}>
              {pending.canRestore && (
                <button
                  type="button"
                  className={styles.primary}
                  disabled={busy}
                  onClick={() => {
                    void restoreDeletedAccount();
                  }}
                >
                  {busy ? t('deletion.working') : t('deletion.restore')}
                </button>
              )}
              <button
                type="button"
                className={pending.canRestore ? styles.secondary : styles.primary}
                disabled={busy}
                onClick={() => {
                  setConfirming(true);
                }}
              >
                {t('deletion.startNew')}
              </button>
            </div>
          </>
        )}
      </section>
      <button
        type="button"
        className={styles.cancel}
        disabled={busy}
        onClick={() => {
          dismissPendingDeletion();
        }}
      >
        {t('deletion.cancel')}
      </button>
    </main>
  );
}
