/**
 * Proof from Google or Apple for a signed-in screen: connecting a sign-in
 * method in Settings, or signing in to the account the learner already had
 * from the "Already have a Lexpad account?" question.
 *
 * Unlike signing in, these screens hold a session that must survive the
 * provider round trip (its access token is fresh, and the server asks for a
 * fresh one), so a browser never leaves the page: Google opens in a popup
 * whose callback hands the code back over a BroadcastChannel, and Apple uses
 * its own popup as on the sign-in page. The shells use their native sheets.
 */
import { useEffect, useRef } from 'react';
import { platform } from '@/lib/platform/index.js';
import { appleWebSignIn, makeAppleNonce, preloadAppleSdk, type AppleNonce } from './appleSignIn.js';

/** What Apple handed over: the token, the raw nonce, and a name the first time. */
export interface AppleProof {
  idToken: string;
  nonce: string;
  displayName?: string;
  /** The authorization code, and on the web the redirect it is bound to. */
  code?: string;
  redirectUri?: string;
}

export type GoogleProof = { code: string } | { idToken: string };

/** The channel the popup callback answers on; same origin only. */
export const GOOGLE_POPUP_CHANNEL = 'lexpad.google-popup';

/** States of popup attempts start with this, so the callback knows to hand back. */
export const GOOGLE_POPUP_STATE_PREFIX = 'popup.';

/**
 * How long a popup attempt waits for its answer. A popup's `closed` flag
 * cannot be trusted once Google's page has isolated it, so a closed popup is
 * not noticed; the attempt gives up after this, or when another starts.
 */
export const GOOGLE_POPUP_WAIT_MS = 5 * 60_000;

/** Thrown when the learner closed the provider's window: a choice, not a failure. */
export class ProofCancelled extends Error {
  constructor() {
    super('cancelled');
  }
}

let cancelPrevious: (() => void) | undefined;

/**
 * Google's proof. Call it straight from a tap: the popup must open in direct
 * answer to it, before anything is awaited.
 */
export function googleProof(): Promise<GoogleProof> {
  const clientId = platform.env.googleClientId;
  if (clientId === '') return Promise.reject(new Error('Google sign-in is not configured'));
  if (platform.signIn.available) {
    return platform.signIn.googleIdToken(clientId).then((idToken) => ({ idToken }));
  }
  const state = `${GOOGLE_POPUP_STATE_PREFIX}${crypto.randomUUID()}`;
  const params = new URLSearchParams({
    client_id: clientId,
    redirect_uri: `${window.location.origin}/auth/google/callback`,
    response_type: 'code',
    scope: 'openid email profile',
    access_type: 'offline',
    prompt: 'select_account',
    state,
  });
  const popup = window.open(
    `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`,
    'lexpad-google',
    'popup,width=480,height=680',
  );
  if (popup === null) return Promise.reject(new Error('The browser blocked the Google window'));
  cancelPrevious?.();
  return new Promise<GoogleProof>((resolve, reject) => {
    const channel = new BroadcastChannel(GOOGLE_POPUP_CHANNEL);
    const done = (): void => {
      window.clearTimeout(timer);
      channel.close();
      if (cancelPrevious === cancel) cancelPrevious = undefined;
    };
    const cancel = (): void => {
      done();
      reject(new ProofCancelled());
    };
    const timer = window.setTimeout(cancel, GOOGLE_POPUP_WAIT_MS);
    cancelPrevious = cancel;
    channel.onmessage = (event: MessageEvent<unknown>) => {
      const data = event.data as { state?: unknown; code?: unknown } | null;
      if (data === null || typeof data !== 'object' || data.state !== state) return;
      done();
      if (typeof data.code === 'string' && data.code !== '') resolve({ code: data.code });
      else reject(new ProofCancelled());
    };
  });
}

/**
 * Apple's proof. In a browser, Apple's script and the next nonce are made
 * ready before the tap, so the popup opens in direct answer to it.
 */
export function useAppleProof(): () => Promise<AppleProof> {
  const nextNonce = useRef<AppleNonce | undefined>(undefined);
  const onWeb = platform.env.appleClientId !== '' && !platform.signIn.appleAvailable;
  useEffect(() => {
    if (!onWeb) return;
    preloadAppleSdk();
    void makeAppleNonce().then((nonce) => {
      nextNonce.current ??= nonce;
    });
  }, [onWeb]);

  return async () => {
    if (platform.env.appleClientId === '') throw new Error('Sign in with Apple is not configured');
    // Each nonce is used once.
    const nonce = nextNonce.current ?? (await makeAppleNonce());
    nextNonce.current = undefined;
    if (onWeb) {
      void makeAppleNonce().then((next) => {
        nextNonce.current ??= next;
      });
    }
    const result = platform.signIn.appleAvailable
      ? await platform.signIn.appleIdToken(nonce.hashed)
      : await appleWebSignIn(platform.env.appleClientId, `${window.location.origin}/auth`, nonce.hashed);
    return {
      idToken: result.idToken,
      nonce: nonce.raw,
      ...(result.displayName === undefined ? {} : { displayName: result.displayName }),
      ...(result.code ? { code: result.code } : {}),
      ...('redirectUri' in result && typeof result.redirectUri === 'string'
        ? { redirectUri: result.redirectUri }
        : {}),
    };
  };
}
