/**
 * Cloudflare Web Analytics for the live web app: cookieless page counts, no
 * personal data, no identifiers stored in the browser.
 *
 * The beacon is added at run time, and only when every one of these holds:
 * the build is a production web build that carries the site token and host
 * (vite.config.ts sets both, and only for the web target), the page is
 * actually served from that host, the app is not inside a shell, and the
 * browser is not being driven by automation. Until 2026-10-12 the tag was
 * written into every production web build, so a build previewed or tested on
 * a laptop (`vite preview`, Playwright) counted as a visit to app.lexpad.app:
 * 98.5% of a week's "visits" came from `localhost`. The native shells report
 * nothing here at all; their use is read from the API's own tables.
 */

/** Cloudflare's beacon. The CSP in vite.config.ts allows exactly this origin. */
export const BEACON_SRC = 'https://static.cloudflareinsights.com/beacon.min.js';

export interface AnalyticsSite {
  /** Cloudflare's public site token; empty or absent means off. */
  token: string | undefined;
  /** The only host whose pages are counted, e.g. `app.lexpad.app`. */
  host: string | undefined;
  /** A production build (`import.meta.env.PROD`). */
  production: boolean;
  /** `location.hostname` of the running page. */
  hostname: string;
  /** Inside the Android, iOS or desktop shell. */
  embedded: boolean;
  /** `navigator.webdriver`: Playwright, Selenium and friends. */
  automated: boolean;
}

export function shouldCount(site: AnalyticsSite): boolean {
  return (
    site.production &&
    !site.embedded &&
    !site.automated &&
    Boolean(site.token) &&
    Boolean(site.host) &&
    site.hostname.toLowerCase() === site.host?.toLowerCase()
  );
}

/** Adds the beacon when `shouldCount` says so; true when it was added. */
export function startWebAnalytics(site: AnalyticsSite, doc: Document = document): boolean {
  if (!shouldCount(site) || !site.token) return false;
  const script = doc.createElement('script');
  script.defer = true;
  script.src = BEACON_SRC;
  script.setAttribute('data-cf-beacon', JSON.stringify({ token: site.token }));
  doc.body.appendChild(script);
  return true;
}
