import { useState } from 'react';
import { Link } from 'react-router-dom';
import { auth as authApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import styles from './SignIn.module.css';

/**
 * Asks for a reset link. The confirmation reads the same whether or not the
 * address has an account, because the API answers the same way.
 */
export function ForgotPassword(): React.JSX.Element {
  const [email, setEmail] = useState('');
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | undefined>();

  const submit: React.SubmitEventHandler<HTMLFormElement> = (event) => {
    event.preventDefault();
    if (!email.includes('@')) {
      setError(t('auth.email'));
      return;
    }
    setBusy(true);
    setError(undefined);
    authApi
      .forgotPassword(email.trim())
      .then(() => {
        setSent(true);
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'offline')) setError(t('error.offline'));
        else if (cause instanceof ApiError && cause.code === 'rate_limited') setError(cause.message);
        else setError(t('error.generic'));
      })
      .finally(() => {
        setBusy(false);
      });
  };

  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('app.name')}</h1>
      </div>
      <form className={styles.form} onSubmit={submit} noValidate>
        <div className={styles.formTitle}>{t('auth.forgotTitle')}</div>
        {sent ? (
          <p className={styles.success} role="status">
            {t('auth.forgotSent')}
          </p>
        ) : (
          <>
            <p className={styles.lead}>{t('auth.forgotLead')}</p>
            <input
              className={styles.input}
              type="email"
              placeholder={t('auth.email')}
              aria-label={t('auth.email')}
              autoComplete="email"
              inputMode="email"
              autoCapitalize="off"
              spellCheck={false}
              value={email}
              onChange={(event) => {
                setEmail(event.target.value);
              }}
            />
            {error !== undefined && (
              <div className={styles.error} role="alert">
                {error}
              </div>
            )}
            <button type="submit" className={styles.submit} disabled={busy}>
              {busy ? t('auth.busy') : t('auth.forgotSend')}
            </button>
          </>
        )}
        <Link to="/auth" className={styles.textLink}>
          {t('auth.backToSignIn')}
        </Link>
      </form>
    </main>
  );
}
