/**
 * ⌘2 / Ctrl+2 from the learning window brings the Player forward (spec
 * uiux/specs/2026-10-25-video-player.md §24.3). On a Mac the Window menu
 * has the same key, so a press reaches whichever answers first; on Windows
 * there is no menu bar and this is the way. Only inside the desktop app with
 * a player.
 */
import { useEffect } from 'react';
import { platform } from '@/lib/platform/index.js';

export function useWindowKeys(): void {
  useEffect(() => {
    const player = platform.desktop?.player;
    if (player === undefined) return;
    const mac = player.window.os === 'macos';
    const onKey = (e: KeyboardEvent): void => {
      const mod = mac ? e.metaKey && !e.ctrlKey : e.ctrlKey && !e.metaKey;
      if (!mod || e.altKey || e.shiftKey || e.key !== '2') return;
      e.preventDefault();
      void player.openWindow('player').catch(() => undefined);
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, []);
}
