/**
 * Whether the navigation beside the page is a narrow rail or a wide sidebar,
 * on a tablet or a computer (lib/windowClass.ts). A phone has the bottom bar
 * and never reads any of this.
 *
 * Until somebody chooses, the window decides: a sidebar from `large` (1180)
 * up, a rail below it. Once they press the toggle (or Ctrl/⌘ + \), their
 * choice holds at every width on this device, the way a desktop app
 * remembers how its window was left.
 *
 * It lives in `platform.prefs` (localStorage) rather than IndexedDB because
 * it has to be known before the first frame: the page is laid out beside
 * the rail, and a rail that changed width once the database answered would
 * shove the whole screen sideways. It is this device's furniture, not the
 * learner's data, so it is not synced.
 *
 * The stylesheets read it from `data-sidebar` on the root element
 * (styles/tokens.css sets `--rail-w` from it); without the attribute they
 * fall back to the window's default, which is the same rule as
 * `sidebarState` below.
 */
import { create } from 'zustand';
import { platform } from './platform/index.js';
import { atLeast, type WindowClass } from './windowClass.js';

export type SidebarState = 'expanded' | 'collapsed';

export const SIDEBAR_KEY = 'lexpad.sidebar';

function isSidebarState(value: string | null): value is SidebarState {
  return value === 'expanded' || value === 'collapsed';
}

/** Stamps the choice on the root element, or clears it when there is none. */
function apply(choice: SidebarState | undefined): void {
  const root = document.documentElement;
  if (choice === undefined) delete root.dataset.sidebar;
  else root.dataset.sidebar = choice;
}

interface SidebarStore {
  /** What the learner chose on this device; undefined until they do. */
  choice: SidebarState | undefined;
  choose: (state: SidebarState) => void;
}

export const useSidebarStore = create<SidebarStore>((set) => {
  const stored = platform.prefs.get(SIDEBAR_KEY);
  return {
    choice: isSidebarState(stored) ? stored : undefined,
    choose(state) {
      platform.prefs.set(SIDEBAR_KEY, state);
      apply(state);
      set({ choice: state });
    },
  };
});

/** What the navigation is at this window size, given the choice. */
export function sidebarState(size: WindowClass, choice: SidebarState | undefined): SidebarState {
  if (choice !== undefined) return choice;
  return atLeast(size, 'large') ? 'expanded' : 'collapsed';
}

/** Applies the stored choice before the first render. Called once at boot. */
export function startSidebar(): void {
  apply(useSidebarStore.getState().choice);
}
