/**
 * The screens a tab tap lands on, fetched and evaluated once the first
 * screen has painted, so a first switch to the notebook, Today or a word
 * never waits on a chunk (tester feedback, 2026-10-09: tab switches felt
 * slow and showed a loading state). The router keeps the current screen
 * until the next one's code is ready, so without this the first tap on a
 * tab sat still while its chunk arrived and ran.
 *
 * The same `import()` the routes use, so the bundler hands back the same
 * chunks; the service worker already holds the files, so this costs no
 * network, only the evaluation that would otherwise happen on the tap.
 */
const SCREENS: readonly (() => Promise<unknown>)[] = [
  () => import('@/features/today/Today.js'),
  () => import('@/features/notebook/NotebookLayout.js'),
  () => import('@/features/notebook/Notebook.js'),
  () => import('@/features/word/WordDetail.js'),
];

/**
 * How long after the first paint to start when the browser has no idle
 * callback (Safari): late enough to stay off the first frame. A feel, not
 * data.
 */
const FALLBACK_DELAY_MS = 600;

/** The longest the idle callback may wait on a page that is never idle. */
const IDLE_TIMEOUT_MS = 2_000;

let started = false;

/** Loads the main screens' code in idle time, once per run of the app. */
export function prefetchScreens(): void {
  if (started) return;
  started = true;
  const load = (): void => {
    for (const screen of SCREENS) {
      // A chunk that fails here is fetched again by the route that needs it.
      void screen().catch(() => undefined);
    }
  };
  if (typeof window.requestIdleCallback === 'function') {
    window.requestIdleCallback(load, { timeout: IDLE_TIMEOUT_MS });
  } else {
    window.setTimeout(load, FALLBACK_DELAY_MS);
  }
}
