/**
 * Seconds on each screen (§9 `screen.time`), counted on this device only
 * while somebody is here (`presence.ts`: shown, focused, not asleep), and
 * sent as one event per screen when the app goes to the background or the
 * sender stops. Nothing runs per frame: the clock is read only when the
 * screen or presence changes.
 */
import { onScreenChange, screenName, screenSurface, signal, type Surface } from '@/lib/surface.js';

export { screenName };
import { isPresent, onPresence } from './presence.js';

/** The most one event may claim (§10: screen.time ≤ 4 h per event). */
export const SCREEN_SECONDS_MAX = 4 * 60 * 60;

const totals = new Map<Surface, number>();
let current: Surface | undefined;
/** When the present stretch on `current` began; undefined while nobody is here. */
let since: number | undefined;

function settle(at: number): void {
  if (current !== undefined && since !== undefined && at > since) {
    totals.set(current, (totals.get(current) ?? 0) + (at - since));
  }
  since = undefined;
}

/** Sends what was counted and starts again from nothing. */
export function flushScreenTime(now: number = Date.now()): void {
  const wasHere = since !== undefined;
  settle(now);
  if (wasHere && isPresent()) since = now;
  for (const [surface, ms] of totals) {
    const seconds = Math.min(SCREEN_SECONDS_MAX, Math.round(ms / 1000));
    if (seconds >= 1) {
      signal({ name: 'screen.time', surface, meta: { screen: screenName(surface), seconds } }, now);
    }
  }
  totals.clear();
}

export function startScreenTime(): () => void {
  current = screenSurface();
  const offPresence = onPresence((here, at) => {
    if (here) since = at;
    else settle(at);
  });
  since = isPresent() ? Date.now() : undefined;
  const offScreen = onScreenChange((next) => {
    const now = Date.now();
    const wasHere = since !== undefined;
    settle(now);
    current = next;
    if (wasHere) since = now;
  });
  return () => {
    offScreen();
    offPresence();
    totals.clear();
    current = undefined;
    since = undefined;
  };
}
