import { useMemo, useState } from 'react';
import { accountAddress } from '@/features/auth/hiddenEmail.js';
import { useSearchParams } from 'react-router-dom';
import { me as meApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { useAuth } from './session.js';
import { desktopCallbackUrl, readDesktopRequest } from './desktopRequest.js';
import styles from './SignIn.module.css';

type Outcome = 'ask' | 'working' | 'done' | 'failed' | 'offline' | 'delegated' | 'cancelled';

/**
 * Where the desktop app sends the learner to be connected (RFC 8252: the
 * system browser, a loopback redirect, PKCE). The learner is signed in here;
 * allowing asks the API for a one-time code bound to the app's challenge and
 * its loopback address, and sends this browser to that address with the code
 * and the app's state. The app trades the code, with a verifier only it
 * holds, for its own session. No token passes through this page, and the
 * app never sees a password.
 *
 * The request in the address is checked before anything is offered
 * (`desktopRequest.ts`): an address that is not exactly the app's loopback
 * callback gets an explanation and no redirect, ever.
 */
export function ConnectDesktop(): React.JSX.Element {
  const [params] = useSearchParams();
  const request = useMemo(() => readDesktopRequest(params), [params]);
  const user = useAuth((s) => s.user);
  const [outcome, setOutcome] = useState<Outcome>('ask');

  const leave = (answer: Record<string, string>): boolean => {
    const target = request === undefined ? undefined : desktopCallbackUrl(request, answer);
    if (target === undefined) return false;
    // A navigation, not a form post: the security policy's form-action stays 'self'.
    window.location.assign(target);
    return true;
  };

  const allow = async (): Promise<void> => {
    if (request === undefined) return;
    setOutcome('working');
    try {
      const { code } = await meApi.createDesktopCode({
        codeChallenge: request.codeChallenge,
        codeChallengeMethod: 'S256',
        redirectUri: request.redirectUri,
      });
      setOutcome(leave({ code }) ? 'done' : 'failed');
    } catch (cause: unknown) {
      if (isApiError(cause) && cause.code === 'delegated_session') setOutcome('delegated');
      else if (isApiError(cause, 'offline')) setOutcome('offline');
      else setOutcome('failed');
    }
  };

  const cancel = (): void => {
    // The app is waiting on its port; telling it no lets it stop waiting.
    leave({ error: 'access_denied' });
    setOutcome('cancelled');
  };

  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('app.name')}</h1>
      </div>
      <div className={styles.form}>
        <div className={styles.formTitle}>{t('connectDesktop.title')}</div>
        {request === undefined && (
          <p className={styles.error} role="alert">
            {t('connectDesktop.invalid')}
          </p>
        )}
        {request !== undefined && (outcome === 'ask' || outcome === 'working') && (
          <>
            <p className={styles.lead}>
              {t('connectDesktop.lead', { email: user === null ? '' : accountAddress(user) })}
            </p>
            <button
              type="button"
              className={styles.submit}
              disabled={outcome === 'working'}
              onClick={() => {
                void allow();
              }}
            >
              {outcome === 'working' ? t('connectDesktop.working') : t('connectDesktop.allow')}
            </button>
            <button
              type="button"
              className={styles.textLink}
              disabled={outcome === 'working'}
              onClick={cancel}
            >
              {t('connectDesktop.cancel')}
            </button>
          </>
        )}
        {outcome === 'done' && (
          <p className={styles.success} role="status">
            {t('connectDesktop.done')}
          </p>
        )}
        {outcome === 'failed' && (
          <p className={styles.error} role="alert">
            {t('connectDesktop.failed')}
          </p>
        )}
        {outcome === 'offline' && (
          <p className={styles.error} role="alert">
            {t('connectDesktop.offline')}
          </p>
        )}
        {outcome === 'delegated' && (
          <p className={styles.error} role="alert">
            {t('connectDesktop.delegated')}
          </p>
        )}
        {outcome === 'cancelled' && (
          <p className={styles.lead} role="status">
            {t('connectDesktop.cancelled')}
          </p>
        )}
      </div>
    </main>
  );
}
