/**
 * The sidebar's two keyboard shortcuts, as pure functions of a key event so
 * they can be tested without a browser.
 *
 * - **N** adds a word, from anywhere the navigation is showing. A single
 *   letter, as Gmail and Linear use for "new", because it is the thing done
 *   most; it is ignored while somebody is typing, while a dialog is open and
 *   with any modifier held, so it can never eat a letter or a browser
 *   shortcut.
 * - **Ctrl + \\** (**⌘ + \\** on a Mac) folds the sidebar into a rail and
 *   opens it again, as in Notion. It works while typing too, since it needs
 *   a modifier to happen.
 *
 * Both match the physical key as well as the character, so they work on a
 * Persian or Russian keyboard, where the N key types something else.
 */

/** Whether focus is somewhere that takes text. */
export function isTyping(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  const tag = target.tagName;
  return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
}

/**
 * Whether a keystroke belongs to a field rather than to the shortcuts: the
 * key went to one, or one holds focus (a key can be aimed at the page while
 * a field is still focused, from a shell or an extension).
 */
export function typingNow(target: EventTarget | null, focused: Element | null): boolean {
  return isTyping(target) || isTyping(focused);
}

/**
 * Whether a press landed on something lying over a text field: `stack` is
 * what is under the pointer, topmost first (`document.elementsFromPoint`).
 * Somebody who taps there meant the field, and focus did not get to it, so
 * the letters they type next are not shortcuts either. A press on the field
 * itself, or on something above it that is not over a field, is not one.
 */
export function coversField(stack: readonly Element[]): boolean {
  const [top, ...below] = stack;
  if (top === undefined || isTyping(top)) return false;
  return below.some(takesText);
}

/** Inputs that are pressed, not typed in: a switch drawn over one is not a field. */
const PRESSED = new Set([
  'checkbox',
  'radio',
  'button',
  'submit',
  'reset',
  'range',
  'color',
  'file',
  'image',
]);

/** Whether an element is somewhere to type text. */
function takesText(element: Element): boolean {
  if (element instanceof HTMLTextAreaElement) return true;
  if (element instanceof HTMLInputElement) return !PRESSED.has(element.type);
  return element instanceof HTMLElement && element.isContentEditable;
}

type KeyLike = Pick<KeyboardEvent, 'key' | 'code' | 'ctrlKey' | 'metaKey' | 'altKey' | 'shiftKey'>;

/** "Add a word": N, with nothing held. */
export function isAddWordKey(event: KeyLike): boolean {
  if (event.ctrlKey || event.metaKey || event.altKey || event.shiftKey) return false;
  return event.key === 'n' || event.key === 'N' || (!/^[a-z]$/i.test(event.key) && event.code === 'KeyN');
}

/** "Fold or open the sidebar": Ctrl + \ or ⌘ + \. */
export function isToggleKey(event: KeyLike): boolean {
  if (!(event.ctrlKey || event.metaKey) || event.altKey || event.shiftKey) return false;
  return event.key === '\\' || event.code === 'Backslash';
}

/** The modifier this computer's keyboard calls it by. */
export function modifierLabel(mac: boolean): string {
  return mac ? '⌘' : 'Ctrl';
}
