/**
 * The system bars, pinned.
 *
 * `env(safe-area-inset-*)` is the browser's answer to "how much of the
 * viewport do the notch, the status bar and the home indicator cover", and
 * on both shells it is unreliable in a different way.
 *
 * On iOS WKWebView the top inset is reported against the visual viewport,
 * so it shrinks while the page is scrolled. Anything that reads it live —
 * a sticky header's own padding, most of all — loses its inset the moment
 * somebody scrolls, and the title ends up under the clock. That is what
 * this exists to stop: the inset is measured once while the page is at rest
 * and written to `--safe-area-inset-*` on the root, and `--safe-top` and
 * `--safe-bottom` in `tokens.css` prefer those over `env()`.
 *
 * On Android WebView `env()` reports the display cutout and nothing else, so
 * a phone with no notch answers zero for a status bar that is really there.
 * The shell writes the true insets to the same two variables; this module
 * never lowers a value the shell has set, so the two cannot fight.
 *
 * The largest value seen on a display, held one way up, wins. A measurement
 * taken mid-scroll or mid-keyboard is always too small, never too large, so
 * taking the maximum is what makes a wrong reading harmless. Turning the
 * phone moves the bars, and so does moving to another display: a foldable
 * iPhone (iPhone Duo) folded shows the app on its outer display with the
 * status bar and camera down one side, and opened shows it on the inner
 * display with them along the top -- both upright, so the orientation never
 * changes. Either one starts a fresh measurement, or the side inset of the
 * outer display would stay pinned beside the content on the inner one. The
 * bars move a few frames apart from the viewport, so a move is measured
 * once more from scratch when it has settled (SETTLE_MS).
 *
 * A zero is never pinned. The iPhone app's web view starts before it is on
 * screen, and until it is, `env()` answers zero for every side; the insets
 * arrive a frame or so later, with no resize event, because the viewport
 * does not change size. Pinning that first zero meant `--safe-top` read
 * 0px for the rest of the session -- the title under the Dynamic Island and
 * the tab bar on the home indicator -- whenever the one late reading came a
 * frame too early, which is a matter of how fast the phone boots. So a side
 * that measures zero is left unset and the tokens fall through to the live
 * `env()`, and a probe that stays in the page reports the moment its
 * `env()` padding changes, so the real value is pinned once it exists.
 */

const SIDES = ['top', 'right', 'bottom', 'left'] as const;
type Side = (typeof SIDES)[number];

/** The largest inset seen since the display or its orientation changed. */
const seen = new Map<Side, number>();
let placement: string | null = null;

/**
 * Whether this page measures the insets alone. The Android shell publishes
 * its own (`env()` there knows only the cutout), so on Android a move to
 * another display is left to the shell exactly as a turn always was; every
 * other host -- the iPhone app, a browser, the desktop app -- has a
 * trustworthy `env()` once the move has settled.
 */
let alone = true;

/**
 * How long after a move the bars are taken to have settled. Unfolding an
 * iPhone Duo reports the inner display's bars before the viewport and the
 * orientation catch up, and the outer display's after: readings in between
 * belong to neither display, and the largest of them would stay pinned. The
 * insets settle within a few frames; this leaves room for a slow phone.
 */
const SETTLE_MS = 400;
let settling: ReturnType<typeof setTimeout> | undefined;

/** The `env()` padding a probe carries: one per side. */
const PROBE_PADDING = [
  'padding-top:env(safe-area-inset-top,0px)',
  'padding-right:env(safe-area-inset-right,0px)',
  'padding-bottom:env(safe-area-inset-bottom,0px)',
  'padding-left:env(safe-area-inset-left,0px)',
];

/**
 * A fixed, empty, invisible element with the four insets as its padding.
 * `env()` is a CSS value with no JavaScript reader, so something has to
 * have it applied before `getComputedStyle` can report a pixel length.
 */
function makeProbe(): HTMLElement {
  const probe = document.createElement('div');
  probe.setAttribute('aria-hidden', 'true');
  probe.style.cssText = [
    'position:fixed',
    'top:0',
    'left:0',
    'width:0',
    'height:0',
    'visibility:hidden',
    'pointer-events:none',
    ...PROBE_PADDING,
  ].join(';');
  return probe;
}

/** Reads the four insets off a probe that is in the page. */
function read(probe: HTMLElement): Record<Side, number> {
  const style = getComputedStyle(probe);
  const side = (name: Side): number => Number.parseFloat(style.getPropertyValue(`padding-${name}`)) || 0;
  return { top: side('top'), right: side('right'), bottom: side('bottom'), left: side('left') };
}

/** Reads the four insets with a probe of its own, removed again at once. */
function measure(): Record<Side, number> {
  const probe = makeProbe();
  document.body.appendChild(probe);
  const insets = read(probe);
  probe.remove();
  return insets;
}

/**
 * Which way up the device is.
 *
 * Asked of the screen rather than worked out from the viewport. Comparing
 * innerWidth with innerHeight looks equivalent and is not: a sheet opening
 * or closing resizes the viewport for a frame or two, and a tall narrow
 * phone can pass through a shape that reads as landscape on the way. That
 * counted as turning the phone, which threw away the remembered inset and
 * wrote whatever the next reading said — and the notebook's sticky header
 * lost its clearance under the clock for the rest of the session.
 *
 * `screen.orientation` does not move until the device really does.
 */
function currentOrientation(): 'portrait' | 'landscape' {
  // Typed as optional because the DOM library says it always exists, and
  // in a web view old enough it does not.
  const orientation = globalThis.screen.orientation as ScreenOrientation | undefined;
  const type = orientation?.type;
  if (typeof type === 'string') return type.startsWith('landscape') ? 'landscape' : 'portrait';
  return window.innerHeight >= window.innerWidth ? 'portrait' : 'landscape';
}

/**
 * Which display the app is on, and which way up: the orientation and the
 * viewport's width. A keyboard or a sheet changes the height, never the
 * width, so neither of them counts; folding or opening a foldable phone puts
 * the app on a display of another width, and that does. The screen's own
 * size would say so more directly, but WebKit keeps reporting the display
 * the page started on (iPhone Duo, iOS 27.1). With the shell publishing the
 * insets, a turn is the only move, as before.
 */
function currentPlacement(): string {
  const orientation = currentOrientation();
  return alone ? `${orientation} ${String(window.innerWidth)}` : orientation;
}

/** Forgets every reading and pins what the bars say now. */
function settle(): void {
  settling = undefined;
  placement = null;
  forget();
  apply();
}

function forget(): void {
  seen.clear();
  for (const side of SIDES) document.documentElement.style.removeProperty(`--safe-area-inset-${side}`);
}

/**
 * Takes one reading and keeps it if it is the largest so far.
 *
 * A viewport with no size teaches nothing. A sheet opening was enough to
 * produce one, and everything measured in it is zero -- including the
 * width, which made a portrait phone look briefly like a landscape one.
 * That cleared the remembered maximum and wrote the zero, and the
 * notebook's header lost its inset for the rest of the session.
 *
 * Whatever is already on the root counts as a reading of its own, so a
 * value the shell published survives a measurement that cannot see it.
 * Turning the phone, or moving to another display, is the one thing that
 * throws that away, because the bars really have moved; the shell publishes again on the same event, and
 * one more reading next frame catches the bars once they have settled.
 */
function apply(): void {
  if (window.innerWidth <= 0 || window.innerHeight <= 0) return;
  const now = currentPlacement();
  const turned = placement !== null && now !== placement;
  placement = now;

  const root = document.documentElement;
  if (turned) {
    forget();
    if (alone) {
      clearTimeout(settling);
      settling = setTimeout(settle, SETTLE_MS);
    }
  }

  const insets = measure();
  for (const side of SIDES) {
    const name = `--safe-area-inset-${side}`;
    const already = Number.parseFloat(root.style.getPropertyValue(name));
    const largest = Math.max(insets[side], seen.get(side) ?? 0, Number.isFinite(already) ? already : 0);
    seen.set(side, largest);
    // A zero is not pinned: it is what every side reads before the web view
    // is on screen, and pinned it would outvote the live env() for good.
    if (largest > 0) root.style.setProperty(name, `${largest}px`);
  }
  if (turned) requestAnimationFrame(apply);
}

/**
 * Keeps one probe in the page and measures again whenever its padding --
 * that is, an inset -- changes. This is what catches the insets arriving
 * after the page has started, which no resize event announces.
 */
function watch(): void {
  if (typeof ResizeObserver === 'undefined') return;
  const probe = makeProbe();
  // Its size is its padding alone, so it changes exactly when an inset does.
  probe.style.boxSizing = 'content-box';
  document.body.appendChild(probe);
  new ResizeObserver(apply).observe(probe, { box: 'border-box' });
}

/**
 * Starts pinning the insets. Called once at boot, before the first render,
 * so no screen ever lays out against a value that is about to change.
 * `shellPublishes` is true where the native shell writes the insets itself
 * (Android).
 */
export function startSafeArea(options: { shellPublishes?: boolean } = {}): void {
  alone = options.shellPublishes !== true;
  apply();
  // A late reading catches the shell finishing its own set-up, and a phone
  // that reports zero until the first frame is on screen.
  requestAnimationFrame(apply);
  watch();
  window.addEventListener('orientationchange', apply);
  window.addEventListener('resize', apply);
  // Back from the background the bars are where they will stay; a reading
  // then costs nothing and mends anything an earlier one missed.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') apply();
  });
}
