import { useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Icon } from '@/components/ui/Icon.js';
import { useUpdate } from '@/lib/useConfig.js';
import { platform } from '@/lib/platform/index.js';
import { t } from '@/i18n/index.js';
import styles from './UpdateGate.module.css';

/**
 * A build the server will no longer have.
 *
 * Distinct from `UpdateToast`, which is the web app noticing its own new
 * bundle and offering a reload. This is the server saying a build is too old
 * — the only thing that reaches a phone, where the app cannot replace itself
 * and somebody has to go to the store.
 *
 * It sits inside the app frame, so the e-mailed links that live outside it —
 * confirming an address, resetting a password — keep working on any build.
 * Somebody locked out of the app must still be able to get back into their
 * account.
 *
 * The block is a screen with no way past it, because a half-blocked app is
 * worse than either: taps that do nothing, and no explanation. The offer is
 * a line at the top that can be dismissed for the session, because an update
 * somebody has decided to do later should not ask again every screen.
 */
export function UpdateGate({ children }: { children: React.ReactNode }): React.JSX.Element {
  const { verdict, url } = useUpdate();
  const [dismissed, setDismissed] = useState(false);

  const open = (): void => {
    if (url !== '') {
      void platform.share.link(url, t('stale.title')).catch(() => undefined);
      return;
    }
    // No address given means the client knows its own way: on the web that
    // is a reload, which is all an update is here.
    window.location.reload();
  };

  if (verdict === 'block') {
    return (
      <main className={styles.screen}>
        <span className={styles.mark} aria-hidden="true">
          <Icon name="arrowRight" size={26} weight={1.8} />
        </span>
        <h1 className={styles.title}>{t('stale.title')}</h1>
        <p className={styles.body}>{t('stale.body')}</p>
        <Button onClick={open}>{t(url === '' ? 'stale.reload' : 'stale.get')}</Button>
        {/* Their words are not stuck inside this build, and saying so is
            the difference between an update and a hostage situation. */}
        <p className={styles.safe}>{t('stale.safe')}</p>
      </main>
    );
  }

  return (
    <>
      {verdict === 'offer' && !dismissed && (
        <div className={styles.bar} role="status">
          <span className={styles.barText}>{t('stale.offer')}</span>
          <button type="button" className={styles.barAction} onClick={open}>
            {t(url === '' ? 'stale.reload' : 'stale.get')}
          </button>
          <button
            type="button"
            className={styles.barClose}
            aria-label={t('action.close')}
            onClick={() => {
              setDismissed(true);
            }}
          >
            <Icon name="close" size={16} weight={2} />
          </button>
        </div>
      )}
      {children}
    </>
  );
}
