import { useLayoutEffect, useRef } from 'react';
import { useRegisterSW } from 'virtual:pwa-register/react';
import { Button } from '@/components/ui/Button.js';
import { isTyping } from '@/features/sidebar/keys.js';
import { t } from '@/i18n/index.js';
import { KEEP_CLEAR_SELECTOR, placeToast, type Box } from './toastPlacement.js';
import styles from './UpdateToast.module.css';

/** Room left at the top of the screen when the toast has to go there. */
const TOP_ROOM = 8;

/**
 * What the toast must not cover right now: whatever the screen marked
 * (Lex's composer) and a focused text field. A dialog's fields are left
 * out: the dialog sits above the toast anyway.
 */
function keepClear(toast: HTMLElement): Box[] {
  const elements = [...document.querySelectorAll<HTMLElement>(KEEP_CLEAR_SELECTOR)];
  const focused = document.activeElement;
  if (focused instanceof HTMLElement && isTyping(focused)) elements.push(focused);
  return elements
    .filter((element) => !toast.contains(element) && element.closest('[aria-modal="true"]') === null)
    .map((element) => element.getBoundingClientRect())
    .filter((box) => box.width > 0 && box.height > 0);
}

/**
 * Keeps the toast off every place to type while it is up, as the screen
 * under it changes: a route with a composer, the soft keyboard, a resize,
 * a field taking focus. Measuring waits for the next frame, so a burst of
 * changes (an answer streaming in) costs one measure.
 */
function useKeepClear(ref: React.RefObject<HTMLDivElement | null>, shown: boolean): void {
  useLayoutEffect(() => {
    const toast = ref.current;
    if (!shown || toast === null) return;
    let frame = 0;
    const measure = (): void => {
      frame = 0;
      // The toast's own spot, from the stylesheet. The computed value, not
      // the box, because the entrance animation is still moving the box.
      toast.removeAttribute('data-edge');
      toast.style.removeProperty('bottom');
      const offset = Number.parseFloat(getComputedStyle(toast).bottom);
      if (!Number.isFinite(offset)) return;
      const { left, right } = toast.getBoundingClientRect();
      const place = placeToast(
        window.innerHeight,
        offset,
        { top: 0, bottom: toast.offsetHeight, left, right },
        keepClear(toast),
        TOP_ROOM,
      );
      if (place.edge === 'top') toast.setAttribute('data-edge', 'top');
      else if (place.offset !== offset) toast.style.bottom = `${place.offset}px`;
    };
    const later = (): void => {
      if (frame === 0) frame = requestAnimationFrame(measure);
    };
    measure();
    const mutations = new MutationObserver(later);
    mutations.observe(document.body, { childList: true, subtree: true });
    const sizes = new ResizeObserver(later);
    sizes.observe(toast);
    for (const element of document.querySelectorAll(KEEP_CLEAR_SELECTOR)) sizes.observe(element);
    window.addEventListener('resize', later);
    window.visualViewport?.addEventListener('resize', later);
    document.addEventListener('focusin', later);
    document.addEventListener('focusout', later);
    return () => {
      if (frame !== 0) cancelAnimationFrame(frame);
      mutations.disconnect();
      sizes.disconnect();
      window.removeEventListener('resize', later);
      window.visualViewport?.removeEventListener('resize', later);
      document.removeEventListener('focusin', later);
      document.removeEventListener('focusout', later);
    };
  }, [ref, shown]);
}

/**
 * A new build is ready. The prompt never interrupts practice: it waits at
 * the bottom until the user chooses to reload, and it never sits on a place
 * to type (see `toastPlacement.ts`).
 */
export function UpdateToast(): React.JSX.Element | null {
  const {
    needRefresh: [needRefresh],
    updateServiceWorker,
  } = useRegisterSW({ immediate: true });
  const ref = useRef<HTMLDivElement>(null);
  useKeepClear(ref, needRefresh);

  if (!needRefresh) return null;

  return (
    <div ref={ref} className={styles.toast} role="status">
      <span className={styles.text}>{t('settings.updateAvailable')}</span>
      <Button
        size="small"
        onClick={() => {
          void updateServiceWorker(true);
        }}
      >
        {t('settings.reload')}
      </Button>
    </div>
  );
}
