/** Android apps that send `android-app://<package>/` as the referrer. */
const APPS: Readonly<Record<string, string>> = {
  'com.google.android.googlequicksearchbox': 'google',
  'com.google.android.youtube': 'youtube',
  'com.reddit.frontpage': 'reddit',
  'org.telegram.messenger': 'telegram',
  'com.instagram.android': 'instagram',
  'com.zhiliaoapp.musically': 'tiktok',
  'com.facebook.katana': 'facebook',
  'com.twitter.android': 'x',
  'com.linkedin.android': 'linkedin',
  'com.whatsapp': 'whatsapp',
  'com.google.android.gm': 'email',
};

/**
 * Sites a visit passes through on its way back to us, which say nothing
 * about where it came from: our own pages, sign-in and payment pages.
 * Matched on the host and every parent domain.
 */
const PASS_THROUGH = new Set([
  'lexpad.app',
  'apple.com',
  'stripe.com',
  'paddle.com',
  'paypal.com',
  'lemonsqueezy.com',
  'microsoftonline.com',
  'live.com',
  'localhost',
]);

/** Google's search hosts: google.com, google.de, google.co.uk, google.com.tr … */
const GOOGLE = /^google\.(?:[a-z]{2,3}|co\.[a-z]{2}|com\.[a-z]{2})$/;
const YANDEX = /^yandex\.(?:[a-z]{2,3}|com\.[a-z]{2})$/;
/** Two-letter country domains under a short second level (co.uk, com.tr). */
const COUNTRY_SECOND_LEVEL = /^(?:co|com|org|net|ac|gov|edu)\.[a-z]{2}$/;

/** The longest word the server takes (domain/referral MaxSourceLength). */
const MAX_LENGTH = 32;

function siteWord(host: string): string | undefined {
  const labels = host.split('.');
  if (labels.length < 2) return undefined;
  const lastTwo = labels.slice(-2).join('.');
  const site =
    COUNTRY_SECOND_LEVEL.test(lastTwo) && labels.length >= 3 ? labels.slice(-3).join('.') : lastTwo;
  const word = site
    .replace(/[^a-z0-9.-]/g, '')
    .replace(/\./g, '-')
    .slice(0, MAX_LENGTH)
    .replace(/[-_]+$/, '');
  return /^[a-z0-9][a-z0-9_-]{0,31}$/.test(word) ? word : undefined;
}

/**
 * The source word for a referrer address, or undefined when it names no
 * outside site (empty, our own pages, a sign-in or payment page, an address
 * that is not a web page).
 */
export function sourceFromReferrer(referrer: string | null | undefined): string | undefined {
  if (typeof referrer !== 'string' || referrer === '') return undefined;
  let url: URL;
  try {
    url = new URL(referrer);
  } catch {
    return undefined;
  }
  if (url.protocol === 'android-app:') return APPS[url.hostname.toLowerCase()];
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return undefined;
  const host = url.hostname
    .toLowerCase()
    .replace(/\.$/, '')
    .replace(/^(?:www|m|mobile)\./, '');
  if (host === '' || /^[\d.]+$/.test(host) || host.includes(':')) return undefined;
  const known = HOSTS[host];
  if (known !== undefined) return known;
  if (GOOGLE.test(host)) return 'google';
  if (YANDEX.test(host)) return 'yandex';
  if (host.endsWith('.search.yahoo.com')) return 'yahoo';
  if (host.endsWith('.chatgpt.com')) return 'chatgpt';
  if (host.endsWith('.perplexity.ai')) return 'perplexity';
  if (host.endsWith('.youtube.com')) return 'youtube';
  if (host.endsWith('.reddit.com')) return 'reddit';
  if (host.endsWith('.facebook.com')) return 'facebook';
  const labels = host.split('.');
  for (let i = 0; i < labels.length; i += 1) {
    if (PASS_THROUGH.has(labels.slice(i).join('.'))) return undefined;
  }
  // Any other Google host (accounts.google.com on the way back from
  // signing in, docs, a country's mail) says nothing about where a visit began.
  if (labels.some((label) => label === 'google' || label === 'googleusercontent')) return undefined;
  return siteWord(host);
}

/** A source word as the server takes it (domain/referral validSource). */
const WORD = /^[a-z0-9][a-z0-9_-]{0,31}$/;

/**
 * A `?ref=` or `utm_source` value as a source word. Assistants and some
 * sites put their own host in `utm_source` (ChatGPT links carry
 * `utm_source=chatgpt.com`), which is not a word the server takes; a value
 * that looks like a host is read like a referrer, so it becomes `chatgpt`
 * and a visit from ChatGPT's apps (which send no referrer) still counts.
 * Anything else that is not a plain word is dropped. `inv-` codes are left
 * to `cleanRef`.
 */
export function sourceFromParam(raw: string | null | undefined): string | undefined {
  if (typeof raw !== 'string') return undefined;
  const value = raw.trim().toLowerCase();
  if (value === '') return undefined;
  if (WORD.test(value)) return value;
  if (/^[a-z0-9.-]+\.[a-z]{2,}$/.test(value)) return sourceFromReferrer(`https://${value}/`);
  return undefined;
}

/**
 * The source word for a Google Play install referrer (the Android shell's
 * `InstallReferrer` plugin; Play's Install Referrer API). Play hands back
 * the `referrer` of the listing link the person followed, URL-encoded
 * (`utm_source=google&utm_medium=...`); lexpad.app's own Play links carry
 * `utm_source=<word>` (landing `site-v7.js`). A person who found the app
 * inside Play gets `utm_source=google-play&utm_medium=organic`, which is
 * `play`. Only `utm_source` is read; click ids and the rest are ignored and
 * never kept.
 */
export function sourceFromInstallReferrer(raw: string | null | undefined): string | undefined {
  if (typeof raw !== 'string' || raw.trim() === '') return undefined;
  let params: URLSearchParams;
  try {
    params = new URLSearchParams(raw.trim());
  } catch {
    return undefined;
  }
  const source = params.get('utm_source')?.trim().toLowerCase() ?? '';
  if (source === '' || source === 'google-play' || source === '(not set)' || source === '(direct)')
    return 'play';
  return sourceFromParam(source) ?? 'play';
}
