import { useEffect, useState } from 'react';
import { NavLink, useLocation, useNavigate } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { ADD_WORD_PATH, TABS, tabMatches, type Tab } from './nav.js';
import { noteEntry } from '@/lib/surface.js';
import styles from './TabBar.module.css';

/** How far down the page the bar waits before it gets out of the way. */
const SHRINK_AFTER = 90;
/** Scroll this far back up and it comes straight back. */
const GROW_BY = 24;

/**
 * The bottom navigation: a capsule that floats clear of the screen edges
 * with the page running underneath it. Hidden during a session and on the
 * auth screens.
 *
 * Two things make it behave like the system's own rather than like a bar
 * that happens to be rounded.
 *
 * It gets out of the way. Scrolling down past a screen's worth drops the
 * labels and pulls the capsule in, so a long list gets the height back;
 * scrolling up brings it straight back, before you have asked for it. That
 * is the behaviour, not the blur, that makes it feel like part of the page.
 *
 * And the lit shape is one element that slides, not five that fade, which
 * is what says the tabs are one control. It holds the icon and the label
 * together, and its whole geometry is CSS driven by the same custom
 * properties as the capsule and by --tab, the index of the tab you are on.
 *
 * That is the point, not a shortcut. It used to be measured in JavaScript
 * from the tab it sat behind, and a ResizeObserver cannot fire until after
 * layout -- so when the bar shrank, the capsule started resizing and the
 * lit shape only set off once the new size had landed. Sharing the
 * properties means one set of transitions drives both and they move
 * together by construction, with nothing left to fall behind.
 */
export function TabBar(): React.JSX.Element {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const matches = (tab: Tab): boolean => tabMatches(tab, pathname);
  const current = TABS.findIndex(matches);

  const [small, setSmall] = useState(false);

  useEffect(() => {
    let last = window.scrollY;
    // Measured from the lowest point since the last move down: a finger
    // moves a few pixels per scroll event, so comparing with the previous
    // event alone almost never saw GROW_BY and the bar stayed small.
    let lowest = last;
    const onScroll = (): void => {
      const y = window.scrollY;
      if (y > last) lowest = y;
      if (y > SHRINK_AFTER && y > last) setSmall(true);
      else if (y < lowest - GROW_BY || y <= SHRINK_AFTER) setSmall(false);
      last = y;
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', onScroll);
    };
  }, []);

  return (
    <nav
      className={cx(styles.bar, small && styles.barSmall)}
      aria-label={t('nav.label')}
      style={{ '--tab': Math.max(current, 0) } as React.CSSProperties}
    >
      {/*
       * The tab you are on is wider than the rest. "Notebook" is 47pt at the
       * weight it takes when selected, and in a 54pt pill that leaves three
       * and a half either side, which reads as cramped however the rest is
       * tuned. Five tabs at the width that word wants do not fit a phone
       * beside the button -- but only one tab is ever selected, so only one
       * has to be that wide.
       *
       * The template is computed rather than measured: it is the same
       * render as --tab, so the widening and the lit shape's slide start on
       * the same frame.
       */}
      <div
        className={styles.inner}
        style={{
          gridTemplateColumns: TABS.map((_, index) =>
            index === current ? 'var(--tab-wide)' : 'var(--tab-w)',
          ).join(' '),
        }}
      >
        <span className={cx(styles.indicator, current < 0 && styles.indicatorOff)} aria-hidden="true" />
        {TABS.map((tab, index) => (
          <NavLink
            key={tab.to}
            to={tab.to}
            end={tab.to === '/'}
            className={cx(styles.tab, matches(tab) && styles.active)}
          >
            {/* The icon and the label share one square, which is what the
                lit circle is drawn around. */}
            <span className={styles.mark} data-mark={index}>
              <span className={styles.icon}>
                <Icon name={tab.icon} size={20} />
              </span>
              <span className={styles.label}>{t(tab.label)}</span>
            </span>
          </NavLink>
        ))}
      </div>

      {/*
       * Writing a word down is what this app is for, and until now it could
       * only be started from the notebook: from Today, with words already
       * saved, there was no way to add one at all. The moment you meet a
       * word is when you want to keep it, and the taps in between are where
       * words get lost.
       *
       * Beside the capsule rather than inside it, because it is not a place
       * you can be -- it is the one thing you do. It shrinks with the bar
       * and disappears with it, which is what a session wants.
       */}
      <button
        type="button"
        className={cx(styles.add, small && styles.addSmall)}
        aria-label={t('add.title')}
        onClick={() => {
          noteEntry('app.quick_add');
          void navigate(ADD_WORD_PATH);
        }}
      >
        <Icon name="plus" size={24} weight={2.2} />
      </button>
    </nav>
  );
}
