import { useEffect } from 'react';
import { create } from 'zustand';
import { config as configApi } from '@/api/endpoints.js';
import { clientName, clientVersion, verdictFor, type UpdateVerdict } from './update.js';
import type { ApiClientConfig } from '@/api/types.js';
import { setActivityOn } from './surface.js';

/**
 * The numbers a screen needs to draw itself, from the server.
 *
 * A cap written into this bundle is a cap that takes three app releases to
 * change, with the web, Android and iOS builds disagreeing in between. So
 * the server holds them and this fetches them once, on the first screen
 * that asks.
 *
 * The fallback is the number that shipped rather than zero or nothing: a
 * field whose length this device could not look up should still be usable,
 * and the server trims anything over its own limit anyway.
 */

/** What the app draws with before the server has answered. */
export const SHIPPED = { read: 4000, paste: 300 } as const;

interface ConfigState {
  text: { read: number; paste: number };
  /**
   * Whether this build is too old. 'ok' until the server has been asked and
   * has said otherwise, so nothing is ever blocked by a request that has not
   * come back yet.
   */
  update: { verdict: UpdateVerdict; url: string };
  /**
   * The VAPID public key browsers subscribe with, or undefined when this
   * deployment sends no browser notifications (or has not answered yet).
   * Without it, Settings offers no switch.
   */
  webPushKey: string | undefined;
  /** The import endpoint's upload cap, once the server has said; nothing is assumed before. */
  importMaxBytes: number | undefined;
  /**
   * Whether the server keeps the files of imports for a day so its team can
   * fix a failed import (`importFileCapture`, the `import_file_capture`
   * flag). False until the server has said so: nothing is sent before.
   */
  importFileCapture: boolean;
  /**
   * The exact hosts a notification's external link may open, from the
   * server's `notification_links` flag. Undefined while external links are
   * switched off, before the server has answered, or when it could not be
   * reached; then no link opens (`safeNotificationUrl`).
   */
  linkHosts: readonly string[] | undefined;
  /**
   * The onboarding plan's measured numbers (`plan`), each absent until the
   * server has enough data; `lib/cardTime.ts` holds the named defaults.
   */
  plan: { secondsPerCard?: number; recall?: number };
  /**
   * The AI cards an account may make before it confirms its e-mail address
   * (`limits.aiCardsUnconfirmed`): undefined while the server has not said
   * (not answered yet, or a server that predates `limits`), null when it sent
   * `limits` without it, which means there is no such gate.
   */
  unconfirmedCards: number | null | undefined;
  /**
   * Each plan's allowances (`limits`), for the Free vs Pro table and the
   * honest Pro line. Each number is absent until the server sends it, and
   * then the screen says the same thing without the number.
   */
  limits: PlanLimits;
  loaded: boolean;
  /**
   * Whether the server's answer (or its failure) has come back, so a screen
   * that draws differently with and without `webPushKey` can wait for it
   * rather than draw one way and then the other.
   */
  answered: boolean;
  /** Reads the numbers once. Calling it again while loaded does nothing. */
  ensure: () => void;
  apply: (next: ApiClientConfig) => void;
}

export const useConfig = create<ConfigState>((set, get) => ({
  text: { ...SHIPPED },
  update: { verdict: 'ok', url: '' },
  webPushKey: undefined,
  importMaxBytes: undefined,
  importFileCapture: false,
  linkHosts: undefined,
  plan: {},
  unconfirmedCards: undefined,
  limits: {},
  loaded: false,
  answered: false,
  ensure: () => {
    if (get().loaded) return;
    // Marked loaded before the answer, so two screens mounting together do
    // not both ask.
    set({ loaded: true });
    void configApi
      .get()
      .then((answer) => {
        get().apply(answer);
      })
      .catch(() => {
        // Offline, or an older server. The shipped numbers stand, and the
        // server trims anything over its own limit regardless. Nothing about
        // activity goes out on a guess (`lib/surface.ts`).
        setActivityOn(false);
        set({ answered: true });
      });
  },
  apply: (next) => {
    // Whether the server takes the surface headers and client events
    // (activity contract §2.1). Not in the generated contract yet, so read
    // loosely: anything but `true` is off.
    setActivityOn((next as { activity?: unknown }).activity === true);
    set({
      text: { read: next.text.read, paste: next.text.paste },
      update: verdictFor(next.update, clientName(), clientVersion()),
      webPushKey: next.webPushKey === '' ? undefined : next.webPushKey,
      importMaxBytes: next.importMaxBytes,
      importFileCapture: next.importFileCapture === true,
      linkHosts: next.linkHosts,
      plan: planFrom(next.plan),
      unconfirmedCards: unconfirmedFrom(next.limits),
      limits: limitsFrom(next.limits),
      answered: true,
    });
  },
}));

/** The unconfirmed account's AI cards: a whole number, null for no gate, undefined when unsaid. */
function unconfirmedFrom(limits: ApiClientConfig['limits']): number | null | undefined {
  if (limits === undefined) return undefined;
  const cards = limits.aiCardsUnconfirmed;
  return typeof cards === 'number' && Number.isInteger(cards) && cards >= 0 ? cards : null;
}

/** One plan's allowances, as GET /config sends them under `limits`. */
export interface PlanAllowances {
  aiCardsDaily?: number;
  aiCardsMonthly?: number;
  lexDaily?: number;
  lexMonthly?: number;
}

/** What the server says each plan includes; empty until it says. */
export interface PlanLimits {
  free?: PlanAllowances;
  pro?: PlanAllowances;
}

const ALLOWANCE_KEYS = ['aiCardsDaily', 'aiCardsMonthly', 'lexDaily', 'lexMonthly'] as const;

/**
 * The plans' allowances, field by field: anything that is not a positive
 * whole number is dropped, so a malformed value is never printed.
 */
export function limitsFrom(raw: unknown): PlanLimits {
  if (raw === null || typeof raw !== 'object') return {};
  const plan = (value: unknown): PlanAllowances | undefined => {
    if (value === null || typeof value !== 'object') return undefined;
    const out: PlanAllowances = {};
    for (const key of ALLOWANCE_KEYS) {
      const n = (value as Record<string, unknown>)[key];
      if (typeof n === 'number' && Number.isInteger(n) && n > 0) out[key] = n;
    }
    return Object.keys(out).length === 0 ? undefined : out;
  };
  const free = plan((raw as { free?: unknown }).free);
  const pro = plan((raw as { pro?: unknown }).pro);
  return { ...(free === undefined ? {} : { free }), ...(pro === undefined ? {} : { pro }) };
}

/** Each plan's allowances, fetched on first use; empty until the server has said. */
export function usePlanLimits(): PlanLimits {
  const limits = useConfig((state) => state.limits);
  const ensure = useConfig((state) => state.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);
  return limits;
}

/** The plan's numbers, kept only when they are numbers in range (anything else is "not measured"). */
function planFrom(plan: ApiClientConfig['plan']): ConfigState['plan'] {
  const seconds = plan?.secondsPerCard;
  const recall = plan?.recall;
  return {
    ...(typeof seconds === 'number' && seconds > 0 && seconds <= 120 ? { secondsPerCard: seconds } : {}),
    ...(typeof recall === 'number' && recall > 0 && recall <= 1 ? { recall } : {}),
  };
}

/** The text caps, fetched on first use. */
export function useTextLimits(): { read: number; paste: number } {
  const text = useConfig((state) => state.text);
  const ensure = useConfig((state) => state.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);
  return text;
}

/** For code that needs the numbers outside React. */
export function textLimits(): { read: number; paste: number } {
  return useConfig.getState().text;
}

/** Whether this build is too old, and where it is updated. */
export function useUpdate(): { verdict: UpdateVerdict; url: string } {
  const update = useConfig((state) => state.update);
  const ensure = useConfig((state) => state.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);
  return update;
}

/** The server's VAPID public key for browser notifications, fetched on first use. */
export function useWebPushKey(): string | undefined {
  const key = useConfig((state) => state.webPushKey);
  const ensure = useConfig((state) => state.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);
  return key;
}

/**
 * The hosts a notification's link may open, fetched on first use, and
 * whether the server has answered yet: a link is neither drawn as working
 * nor as refused before it has.
 */
export function useLinkHosts(): { hosts: readonly string[] | undefined; answered: boolean } {
  const hosts = useConfig((state) => state.linkHosts);
  const answered = useConfig((state) => state.answered);
  const ensure = useConfig((state) => state.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);
  return { hosts, answered };
}

/**
 * Whether a file is over the import endpoint's upload cap, as far as this
 * client knows. Before the server has said, nothing is refused here: the
 * server refuses it itself (file_too_large).
 */
export function overImportLimit(bytes: number): boolean {
  const limit = useConfig.getState().importMaxBytes;
  return limit !== undefined && bytes > limit;
}

/**
 * Whether the file of an import this app ran itself should be handed to
 * the server's one-day copy: only while the server says it keeps them, and
 * only within the import endpoint's own upload cap, which must be known.
 */
export function capturesImportFile(bytes: number): boolean {
  const { importFileCapture, importMaxBytes } = useConfig.getState();
  return importFileCapture && importMaxBytes !== undefined && bytes > 0 && bytes <= importMaxBytes;
}
