type Mode = 'signIn' | 'signUp';

/** The minimum the API will accept, checked here so the round trip is saved. */
const MIN_PASSWORD = 8;

/**
 * How the form is framed. `page` is the sign-in screen at /auth; `sheet` is
 * the onboarding account sheet (onboarding v2 spec §4.7): the same form and
 * the same sign-in paths in a bottom sheet, with the caller's title and
 * lead, the providers first and the e-mail form one tap away.
 */
interface SignInProps {
  frame?: 'page' | 'sheet';
  /** The sheet's title (sheet frame only). */
  title?: string;
  /** The line under the title (sheet frame only). */
  lead?: string;
  /** Drawn above the title (sheet frame only): the learner's word as a chip. */
  top?: React.ReactNode;
}

/**
 * Sign in and create account, in one form. Validation runs on submit only,
 * so typing is never interrupted by an error that has not happened yet.
 */
export function SignIn({ frame = 'page', title, lead, top }: SignInProps = {}): React.JSX.Element {
  const pendingDeletion = useAuth((state) => state.pendingDeletion);
  // The desktop app never takes a password in its window: it connects in the
  // system browser, where Google and Apple work too.
  if (platform.desktop !== undefined) return <DesktopSignIn />;
  // The last sign-in reached an account in its deletion grace: the choice
  // takes the form's place until it is made or dismissed. In the sheet it
  // is the sign-in screen's to show, which reads the same store.
  if (pendingDeletion !== null) {
    if (frame === 'sheet') return <Navigate to="/auth" replace />;
    return <PendingDeletionChoice pending={pendingDeletion} />;
  }
  if (frame === 'sheet') return <SheetSignIn title={title ?? ''} lead={lead ?? ''} top={top} />;
  return <PasswordSignIn />;
}

/**
 * What is wrong with each field, said under that field (app audit
 * 2026-10-22): an empty "Sign in" used to show a red "Email" and nothing
 * else. Undefined while nothing has been tried, or while the field is fine.
 */
function fieldProblems(
  touched: boolean,
  mode: Mode,
  email: string,
  password: string,
): { email: string | undefined; password: string | undefined } {
  if (!touched) return { email: undefined, password: undefined };
  const address = email.trim();
  return {
    email:
      address === '' ? t('auth.emailMissing') : !address.includes('@') ? t('auth.emailInvalid') : undefined,
    password:
      password === ''
        ? t('auth.passwordMissing')
        : mode === 'signUp' && password.length < MIN_PASSWORD
          ? t('auth.passwordShort')
          : undefined,
  };
}

/**
 * One labelled field with its own complaint under it. The label stays
 * visible while typing (a placeholder disappears); the password field has a
 * show/hide button.
 */
function AuthField({
  kind,
  value,
  onChange,
  problem,
  autoComplete,
  autoFocus = false,
}: {
  kind: 'email' | 'password';
  value: string;
  onChange: (value: string) => void;
  problem: string | undefined;
  autoComplete: string;
  autoFocus?: boolean;
}): React.JSX.Element {
  const id = useId();
  const [shown, setShown] = useState(false);
  const label = kind === 'email' ? t('auth.email') : t('auth.password');
  return (
    <div className={styles.field}>
      <label className={styles.label} htmlFor={id}>
        {label}
      </label>
      <div className={styles.inputWrap}>
        <input
          id={id}
          className={cx(styles.input, problem !== undefined && styles.inputBad)}
          type={kind === 'email' ? 'email' : shown ? 'text' : 'password'}
          autoComplete={autoComplete}
          {...(kind === 'email'
            ? { inputMode: 'email' as const, autoCapitalize: 'off', spellCheck: false }
            : { autoCapitalize: 'off', spellCheck: false })}
          autoFocus={autoFocus}
          aria-invalid={problem !== undefined}
          aria-describedby={problem === undefined ? undefined : `${id}-problem`}
          value={value}
          onChange={(event) => {
            onChange(event.target.value);
          }}
        />
        {kind === 'password' && (
          <button
            type="button"
            className={styles.reveal}
            aria-label={t('auth.showPassword')}
            aria-pressed={shown}
            onClick={() => {
              setShown(!shown);
            }}
          >
            <Icon name={shown ? 'eyeOff' : 'eye'} size={18} weight={1.9} />
          </button>
        )}
      </div>
      {problem !== undefined && (
        <p id={`${id}-problem`} className={styles.fieldProblem} role="alert">
          {problem}
        </p>
      )}
    </div>
  );
}

/** The fields and the submit button, shared by the page and the sheet. */
function useSignInForm(initial: Mode): {
  mode: Mode;
  switchMode: () => void;
  email: string;
  setEmail: (value: string) => void;
  password: string;
  setPassword: (value: string) => void;
  problem: string | undefined;
  problems: { email: string | undefined; password: string | undefined };
  busy: boolean;
  submit: React.SubmitEventHandler<HTMLFormElement>;
} {
  const [mode, setMode] = useState<Mode>(initial);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [touched, setTouched] = useState(false);
  const { busy, error, signIn, signUp, clearError } = useAuth();
  const problems = fieldProblems(touched, mode, email, password);
  const submit: React.SubmitEventHandler<HTMLFormElement> = (event) => {
    event.preventDefault();
    setTouched(true);
    const now = fieldProblems(true, mode, email, password);
    if (now.email !== undefined || now.password !== undefined) return;
    void (mode === 'signIn' ? signIn(email.trim(), password) : signUp(email.trim(), password));
  };
  return {
    mode,
    switchMode: () => {
      setMode(mode === 'signIn' ? 'signUp' : 'signIn');
      setTouched(false);
      clearError();
    },
    email,
    setEmail,
    password,
    setPassword,
    problem: error ?? undefined,
    problems,
    busy,
    submit,
  };
}

/**
 * The e-mail and password fields, the one complaint line and submit. The
 * sheet says the news line in its fine print, under every way in.
 */
function EmailFields({
  form,
  autoFocus = false,
}: {
  form: ReturnType<typeof useSignInForm>;
  autoFocus?: boolean;
}): React.JSX.Element {
  return (
    <>
      <AuthField
        kind="email"
        autoComplete="email"
        autoFocus={autoFocus}
        value={form.email}
        onChange={form.setEmail}
        problem={form.problems.email}
      />
      <AuthField
        kind="password"
        autoComplete={form.mode === 'signIn' ? 'current-password' : 'new-password'}
        value={form.password}
        onChange={form.setPassword}
        problem={form.problems.password}
      />
      {form.problem !== undefined && (
        <div className={styles.error} role="alert">
          {form.problem}
        </div>
      )}
      <button type="submit" className={styles.submit} disabled={form.busy}>
        {form.busy ? t('auth.busy') : form.mode === 'signIn' ? t('auth.signIn') : t('auth.signUp')}
      </button>
    </>
  );
}

/**
 * The account sheet's body (onboarding v2 spec §4.7): Google, Apple where
 * the page shows it today, "or", then "Continue with e-mail", which opens
 * the same form in place. Signing in (not up) is one tap away in the fine
 * print and switches the same form, so the learner never leaves the sheet.
 */
function SheetSignIn({
  title,
  lead,
  top,
}: {
  title: string;
  lead: string;
  top: React.ReactNode;
}): React.JSX.Element {
  const form = useSignInForm('signUp');
  const [emailOpen, setEmailOpen] = useState(false);
  const [note, setNote] = useState<string | undefined>(undefined);
  const heading = useRef<HTMLHeadingElement>(null);
  useEffect(() => {
    markIntroSeen();
    heading.current?.focus();
  }, []);
  return (
    <div className={styles.sheetBody}>
      {top}
      <h2 ref={heading} className={styles.sheetTitle} tabIndex={-1}>
        {form.mode === 'signIn' ? t('auth.welcomeBack') : title}
      </h2>
      {form.mode === 'signUp' && <p className={styles.sheetLead}>{lead}</p>}
      <form className={styles.sheetForm} onSubmit={form.submit} noValidate>
        <ProviderButtons
          onNote={(message) => {
            setNote(message);
          }}
        />
        {note !== undefined && (
          <div className={styles.note} role="status">
            {note}
          </div>
        )}
        <div className={styles.divider}>
          <span className={styles.rule} />
          <span className={styles.dividerLabel}>{t('auth.or')}</span>
          <span className={styles.rule} />
        </div>
        {emailOpen || form.mode === 'signIn' ? (
          <EmailFields form={form} autoFocus />
        ) : (
          <button
            type="button"
            className={styles.google}
            onClick={() => {
              setEmailOpen(true);
            }}
          >
            {t('onb.acc.email')}
          </button>
        )}
      </form>
      <p className={styles.fine}>
        {form.mode === 'signUp' && (
          <>
            {t('auth.newsLine')}
            <br />
          </>
        )}
        {fill(t('onb.acc.fine'), {
          terms: (
            <a key="terms" href={ABOUT_LINKS.terms} target="_blank" rel="noopener noreferrer">
              {t('onb.acc.terms')}
            </a>
          ),
          privacy: (
            <a key="privacy" href={ABOUT_LINKS.privacy} target="_blank" rel="noopener noreferrer">
              {t('onb.acc.privacy')}
            </a>
          ),
        })}
        <br />
        {form.mode === 'signUp' ? (
          fill(t('onb.acc.signIn'), {
            link: (
              <button key="in" type="button" className={styles.fineLink} onClick={form.switchMode}>
                {t('onb.acc.signInLink')}
              </button>
            ),
          })
        ) : (
          <button type="button" className={styles.fineLink} onClick={form.switchMode}>
            {t('auth.toSignUp')}
          </button>
        )}
      </p>
    </div>
  );
}

/** Puts elements into a translated sentence's `{name}` places, keeping the words around them. */
function fill(template: string, parts: Record<string, React.ReactNode>): React.ReactNode[] {
  return template.split(/(\{\w+\})/).map((piece, index) => {
    const name = /^\{(\w+)\}$/.exec(piece)?.[1];
    return name !== undefined && name in parts ? parts[name] : <span key={`t${String(index)}`}>{piece}</span>;
  });
}

function PasswordSignIn(): React.JSX.Element {
  // The introduction's last screen lands here already in sign-up mode.
  const [params] = useSearchParams();
  const [mode, setMode] = useState<Mode>(params.get('mode') === 'signup' ? 'signUp' : 'signIn');
  useEffect(() => {
    markIntroSeen();
  }, []);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [touched, setTouched] = useState(false);
  const [note, setNote] = useState<string | undefined>(undefined);
  const { busy, error, signIn, signUp, clearError } = useAuth();

  const problems = fieldProblems(touched, mode, email, password);

  const submit: React.SubmitEventHandler<HTMLFormElement> = (event) => {
    event.preventDefault();
    setTouched(true);
    const now = fieldProblems(true, mode, email, password);
    if (now.email !== undefined || now.password !== undefined) return;
    void (mode === 'signIn' ? signIn(email.trim(), password) : signUp(email.trim(), password));
  };

  // Each field says its own complaint; this line is the server's answer.
  const problem = error ?? undefined;

  const switchMode = (): void => {
    setMode(mode === 'signIn' ? 'signUp' : 'signIn');
    setTouched(false);
    clearError();
  };

  // The word typed on the introduction, if one came: sign-up is then about
  // keeping it, and the page says so. Read, never taken; onboarding takes it.
  const location = useLocation();
  const [introWord] = useState(() => wordFromState(location.state) ?? peekDraftWord());
  const saving = mode === 'signUp' && introWord !== undefined;

  // Arrived by a friend's invitation: the page says what it brings, with
  // the days the server gives (absent while invitations are switched off,
  // and then nothing is said).
  const [invitedDays, setInvitedDays] = useState<number | undefined>(undefined);
  useEffect(() => {
    if (!isInvite(pendingRef()) || !invitesInThisApp()) return;
    let live = true;
    config
      .get()
      .then((answer) => {
        if (live) setInvitedDays(answer.referralDays);
      })
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, []);

  const providers = (
    <ProviderButtons
      onNote={(message) => {
        setNote(message);
      }}
    />
  );
  const providerNote = note !== undefined && (
    <div className={styles.note} role="status">
      {note}
    </div>
  );
  const divider = (
    <div className={styles.divider}>
      <span className={styles.rule} />
      <span className={styles.dividerLabel}>{t('auth.or')}</span>
      <span className={styles.rule} />
    </div>
  );

  return (
    <main className={styles.wrap}>
      {saving ? (
        // The brand shrinks to its mark: the word is what this page is about.
        <div className={styles.brand}>
          <div className={styles.mark} aria-hidden="true">
            <Icon name="notebook" size={22} weight={2} />
          </div>
          <h1 className={cx(styles.name, styles.saveTitle)}>
            {t('intro.saveTitle', { word: `\u2068${introWord}\u2069` })}
          </h1>
          <p className={styles.tagline}>{t('intro.saveLead')}</p>
        </div>
      ) : (
        <div className={styles.brand}>
          <div className={styles.mark}>
            <Icon name="notebook" size={22} weight={2} />
          </div>
          <h1 className={styles.name}>{t('app.name')}</h1>
          <p className={styles.tagline}>{t('auth.tagline')}</p>
          {mode === 'signUp' && invitedDays !== undefined && (
            <p className={styles.invited} role="status">
              {t('auth.invited', { days: invitedDays })}
            </p>
          )}
        </div>
      )}

      <form className={styles.form} onSubmit={submit} noValidate>
        {/* Google and Apple first, then "or", then e-mail, on both sign-up
            and sign-in (app audit 2026-10-22): most people pick the one-tap
            ways, and one order means one thing to learn. */}
        {providers}
        {providerNote}
        {divider}
        {!saving && (
          <div className={styles.formTitle}>
            {mode === 'signIn' ? t('auth.welcomeBack') : t('auth.createTitle')}
          </div>
        )}

        <AuthField
          kind="email"
          autoComplete="email"
          value={email}
          onChange={setEmail}
          problem={problems.email}
        />
        <AuthField
          kind="password"
          autoComplete={mode === 'signIn' ? 'current-password' : 'new-password'}
          value={password}
          onChange={setPassword}
          problem={problems.password}
        />

        {/* Said, not asked (owner, 2026-10-25): news e-mails are on for
            every account and Settings turns them off. */}
        {mode === 'signUp' && <p className={styles.newsLine}>{t('auth.newsLine')}</p>}

        {problem !== undefined && (
          <div className={styles.error} role="alert">
            {problem}
          </div>
        )}

        <button type="submit" className={styles.submit} disabled={busy}>
          {busy ? t('auth.busy') : mode === 'signIn' ? t('auth.signIn') : t('auth.signUp')}
        </button>
        {mode === 'signIn' && (
          <Link to="/forgot" className={styles.textLink}>
            {t('auth.forgot')}
          </Link>
        )}
      </form>

      <button type="button" className={styles.switch} onClick={switchMode}>
        {mode === 'signIn' ? t('auth.toSignUp') : t('auth.toSignIn')}
      </button>
    </main>
  );
}

/**
 * Signing in inside the desktop app: one button that opens Lexpad in the
 * system browser (RFC 8252), where the learner signs in or creates an
 * account with a password, Google or Apple, and allows this computer. The
 * app's core receives the answer; this window only waits for it.
 */
function DesktopSignIn(): React.JSX.Element {
  useEffect(() => {
    markIntroSeen();
  }, []);
  const { busy, error, connectDesktop, cancelDesktopConnect } = useAuth();
  // Which button the learner pressed, so only that one says it is waiting.
  const [via, setVia] = useState<'google' | 'apple' | 'other' | null>(null);
  const go = (which: 'google' | 'apple' | 'other'): void => {
    setVia(which);
    void connectDesktop(which === 'other' ? undefined : which).finally(() => {
      setVia(null);
    });
  };
  const waiting = (which: 'google' | 'apple' | 'other'): boolean => busy && via === which;
  // One sign-in voice in the desktop app (desktop first-run spec §7): the
  // Start window's words, the same two providers, and every other way on
  // the connect page. The sign-in itself is always the system browser.
  return (
    <main className={styles.desktopWrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('auth.desktopTitle')}</h1>
        <p className={styles.tagline}>{t('auth.desktopLead')}</p>
      </div>
      <div className={styles.form}>
        {error !== null && (
          <div className={styles.error} role="alert">
            {error}
          </div>
        )}
        <button
          type="button"
          className={styles.google}
          disabled={busy}
          onClick={() => {
            go('google');
          }}
        >
          <GoogleMark size={20} />
          {waiting('google') ? t('auth.desktopWaiting') : t('auth.google')}
        </button>
        <button
          type="button"
          className={styles.apple}
          disabled={busy}
          onClick={() => {
            go('apple');
          }}
        >
          <AppleMark size={20} />
          {waiting('apple') ? t('auth.desktopWaiting') : t('auth.apple')}
        </button>
        {busy ? (
          <>
            <p className={styles.note} role="status">
              {t('auth.desktopWaitingNote')}
            </p>
            <button
              type="button"
              className={styles.desktopLink}
              onClick={() => {
                void cancelDesktopConnect();
              }}
            >
              {t('auth.desktopCancel')}
            </button>
          </>
        ) : (
          <>
            <p className={styles.note}>{t('auth.desktopFine')}</p>
            <button
              type="button"
              className={styles.desktopLink}
              onClick={() => {
                go('other');
              }}
            >
              {t('auth.desktopOther')}
            </button>
          </>
        )}
      </div>
    </main>
  );
}

/**
 * The two provider buttons the design always shows. Each is live only when
 * its provider is configured; otherwise it says so rather than failing
 * silently, because a button that does nothing reads as broken.
 *
 * Google runs the authorization-code flow: the code is exchanged by the
 * backend, never here, so no client secret ever touches the browser. Apple
 * hands the browser an identity token through its own popup; the backend
 * verifies it against Apple's keys.
 */
function ProviderButtons({ onNote }: { onNote: (message: string) => void }): React.JSX.Element {
  const { signInWithApple, signInWithGoogle } = useAuth();
  const [appleBusy, setAppleBusy] = useState(false);
  const location = useLocation();
  // In a browser, Apple's script and the next nonce are made ready before
  // the tap, so the popup opens in direct answer to it (see appleWebSignIn).
  const nextNonce = useRef<AppleNonce | undefined>(undefined);
  const appleOnWeb = platform.env.appleClientId !== '' && !platform.signIn.appleAvailable;
  useEffect(() => {
    if (!appleOnWeb) return;
    preloadAppleSdk();
    void makeAppleNonce().then((nonce) => {
      nextNonce.current ??= nonce;
    });
  }, [appleOnWeb]);

  const startGoogle = (): void => {
    if (platform.env.googleClientId === '') {
      onNote(t('auth.providerNotConfigured', { provider: 'Google' }));
      return;
    }
    // A shell signs in through the platform SDK and hands the API the ID
    // token; a browser is sent through Google's redirect flow.
    if (platform.signIn.available) {
      void platform.signIn
        .googleIdToken(platform.env.googleClientId)
        .then((idToken) => signInWithGoogle({ idToken }))
        .catch((error: unknown) => {
          // Closing the sheet is a choice, not a failure.
          if (isSignInCancelled(error)) return;
          // The SDK's own words are the only clue to a console misconfiguration.
          const reason = error instanceof Error ? error.message : String(error);
          onNote(t('auth.providerFailedReason', { provider: 'Google', reason }));
        });
      return;
    }
    // Leaving for Google drops the router state that says where to go after.
    rememberReturnPath((location.state as { from?: unknown } | null)?.from);
    const redirectUri = `${window.location.origin}/auth/google/callback`;
    const params = new URLSearchParams({
      client_id: platform.env.googleClientId,
      redirect_uri: redirectUri,
      response_type: 'code',
      scope: 'openid email profile',
      access_type: 'offline',
      prompt: 'select_account',
      state: issueOAuthState(),
    });
    window.location.assign(`https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`);
  };

  // The desktop app's one tap (welcome, the Player's card): Google starts at
  // once (a redirect needs no tap); Apple's popup needs one, so its button
  // takes the focus.
  const appleButton = useRef<HTMLButtonElement>(null);
  const hinted = useRef(false);
  useEffect(() => {
    if (hinted.current) return;
    hinted.current = true;
    const hint = desktopProviderHint((location.state as { from?: unknown } | null)?.from);
    if (hint === 'google') startGoogle();
    if (hint === 'apple') appleButton.current?.focus();
    // Once, as the page opens on the app's request.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const startApple = async (): Promise<void> => {
    if (platform.env.appleClientId === '') {
      onNote(t('auth.providerNotConfigured', { provider: 'Apple' }));
      return;
    }
    setAppleBusy(true);
    try {
      // Apple gets the nonce's hash; the API gets the nonce with the token.
      // Each nonce is used once.
      const nonce = nextNonce.current ?? (await makeAppleNonce());
      nextNonce.current = undefined;
      if (appleOnWeb) {
        void makeAppleNonce().then((next) => {
          nextNonce.current ??= next;
        });
      }
      // The iPhone app uses the system sheet; a browser uses Apple's popup.
      // The popup's return address is registered on the Services ID.
      const result = platform.signIn.appleAvailable
        ? await platform.signIn.appleIdToken(nonce.hashed)
        : await appleWebSignIn(platform.env.appleClientId, `${window.location.origin}/auth`, nonce.hashed);
      await signInWithApple({ ...result, nonce: nonce.raw });
    } catch (error: unknown) {
      // Closing Apple's sheet or popup is a choice, not a failure.
      if (!isSignInCancelled(error)) onNote(t('auth.providerFailed', { provider: 'Apple' }));
    } finally {
      setAppleBusy(false);
    }
  };

  return (
    <>
      <button type="button" className={styles.google} onClick={startGoogle}>
        <GoogleMark size={20} />
        {t('auth.google')}
      </button>
      {platform.env.appleClientId !== '' && (
        // Apple sign-in appears once the Services ID is configured; until
        // then a button that can only apologise is noise.
        // Apple's own look (Human Interface Guidelines): black on a light
        // page, white on a dark one, the logo and title in one colour.
        <button
          ref={appleButton}
          type="button"
          className={styles.apple}
          disabled={appleBusy}
          onClick={() => {
            void startApple();
          }}
        >
          <AppleMark size={20} />
          {t('auth.apple')}
        </button>
      )}
    </>
  );
}
