import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { RouterProvider } from 'react-router-dom';
import { Crashed } from './app/Crashed.js';
import { createRouter } from './app/routes.js';
import { ErrorBoundary, startMonitoring } from './lib/monitoring.js';
import { startSafeArea } from './lib/safeArea.js';
import { startSidebar } from './lib/sidebar.js';
import { startTheme } from './lib/theme.js';
import { startWebAnalytics } from './lib/webAnalytics.js';
import { registerDevice, useAuth, watchSessionEnd } from './features/auth/session.js';
import { noteArrival } from './features/auth/arrival.js';
import { platform } from './lib/platform/index.js';
import { noteInstallRef, noteRef } from './features/invite/ref.js';
import { setScreenSurface, surfaceForPath } from './lib/surface.js';
import './styles/base.css';

startMonitoring();
// Page counts for the live site only: never a local preview, a test run or a shell.
startWebAnalytics({
  token: import.meta.env.VITE_WEB_ANALYTICS_TOKEN,
  host: import.meta.env.VITE_WEB_ANALYTICS_HOST,
  production: import.meta.env.PROD,
  hostname: window.location.hostname,
  embedded: platform.env.embedded,
  automated: navigator.webdriver,
});
startTheme();
// The rail's width is part of the page's layout, so it is known before the
// first frame rather than after the first one shoves the page sideways.
startSidebar();
// Before the first render: every screen pads itself against the system bars,
// and a screen laid out against an inset that is about to change is a screen
// with its title under the clock.
// The Android shell publishes the insets itself (lib/safeArea.ts).
startSafeArea({ shellPublishes: platform.env.platform === 'android' });
watchSessionEnd();
// Where this visit came from (?ref= or utm_source, a friend's invitation,
// else the referring site's host as a word), kept for the sign-up it may
// lead to and sent once after it.
noteRef(window.location.search, Date.now(), { referrer: document.referrer, path: window.location.pathname });
// Inside the Android app: where Google Play says this install came from, once.
void noteInstallRef();
// The lifecycle note this visit was opened through (features/auth/arrival.ts),
// sent once with the device registration. A shell opens app links and push
// taps by setting the hash route, so a later one is noted there and sent at
// once when already signed in.
noteArrival(window.location.search);
noteArrival(window.location.hash);
window.addEventListener('hashchange', () => {
  if (noteArrival(window.location.hash) && useAuth.getState().status === 'ready') void registerDevice();
});
// Decides between the app and sign-in. The gate shows a spinner until it
// resolves, which is the only moment the app waits for anything.
void useAuth.getState().boot();

const container = document.getElementById('root');
if (!container) throw new Error('index.html is missing #root');

// Where the learner is, for the surface the API is told (lib/surface.ts):
// set before the first screen draws, then on every navigation.
const router = createRouter();
setScreenSurface(surfaceForPath(router.state.location.pathname));
router.subscribe((state) => {
  setScreenSurface(surfaceForPath(state.location.pathname));
});

createRoot(container).render(
  <StrictMode>
    <ErrorBoundary fallback={<Crashed />}>
      <RouterProvider router={router} />
    </ErrorBoundary>
  </StrictMode>,
);
// The first frame is on its way; a native shell hides its splash and wires
// the back button, status bar and network from here.
platform.lifecycle.ready();
