/**
 * When an answered card moves on (tester feedback, 2026-10-12): after a
 * mistake the right answer used to flash for 1.6 s and the card left on its
 * own, before a learner who had guessed could read what it should have been.
 *
 * Three choices, Settings → Practice → "After an answer", kept on this
 * device like the other choices about how practice feels there (No timer,
 * Celebrations, Show tips):
 *
 * - `waitAfterMistake` (the default, also for everybody who had never
 *   chosen): a right answer moves on by itself as it always has; a wrong one
 *   stays, with the right answer shown, until the learner taps Next.
 * - `alwaysWait`: every answer waits for Next.
 * - `auto`: every answer moves on by itself, a wrong one after
 *   `WRONG_SHOWN_MS`, long enough to read the answer.
 *
 * The rule is pure and lives here, so the session and the untimed Speed
 * round decide it the same way, and the tests pin each case.
 */
import { getMeta, setMeta } from '@/db/schema.js';

export type AfterAnswer = 'waitAfterMistake' | 'alwaysWait' | 'auto';

/** In the order Settings lists them. */
export const AFTER_ANSWER_CHOICES: readonly AfterAnswer[] = ['waitAfterMistake', 'alwaysWait', 'auto'];

/** What a device that never chose gets: the testers' fix, for existing learners too. */
export const AFTER_ANSWER_DEFAULT: AfterAnswer = 'waitAfterMistake';

/**
 * How long a right answer stays marked before the next card: long enough to
 * see the green, short enough that a run of right answers keeps its rhythm
 * (the prototype's value, unchanged).
 */
export const CORRECT_SHOWN_MS = 700;

/**
 * How long a wrong answer stays when the learner chose "Move on
 * automatically": long enough to read the right answer. It was 1.6 s, which
 * the testers found too short to read.
 */
export const WRONG_SHOWN_MS = 3000;

/**
 * How long an answered card stays when a tip is said about it (the first
 * miss, the first answer kept as practice): long enough to read one sentence.
 */
export const TIP_READ_MS = 3200;

/** Speed round, timed: a right answer is marked this long (the game's own pace). */
export const SPEED_RIGHT_SHOWN_MS = 260;

/**
 * Speed round, timed: a wrong answer stays this long. The clock is the game,
 * so a timed round never waits for Next; the missed words are listed at its end.
 */
export const SPEED_WRONG_SHOWN_MS = 900;

/** Reads a stored value; anything unknown (an older or newer build) is the default. */
export function afterAnswerOf(value: unknown): AfterAnswer {
  return AFTER_ANSWER_CHOICES.find((choice) => choice === value) ?? AFTER_ANSWER_DEFAULT;
}

/** Whether an answer with this outcome waits for Next under this choice. */
export function waitsForNext(after: AfterAnswer, outcome: 'correct' | 'wrong'): boolean {
  if (after === 'alwaysWait') return true;
  if (after === 'auto') return false;
  return outcome === 'wrong';
}

/**
 * A session card: how long the answered card stays before it moves on by
 * itself, or `null` when it waits for Next. A tip said about the answer
 * gets the time to be read.
 */
export function sessionAdvanceMs(
  after: AfterAnswer,
  outcome: 'correct' | 'wrong',
  tip: boolean,
): number | null {
  if (waitsForNext(after, outcome)) return null;
  const shown = outcome === 'correct' ? CORRECT_SHOWN_MS : WRONG_SHOWN_MS;
  return tip ? Math.max(shown, TIP_READ_MS) : shown;
}

/**
 * A Speed round question: the timed round keeps its own pace whatever the
 * choice; "No timer" is the learner's own pace, so it follows the choice.
 */
export function speedAdvanceMs(after: AfterAnswer, correct: boolean, timed: boolean): number | null {
  if (timed) return correct ? SPEED_RIGHT_SHOWN_MS : SPEED_WRONG_SHOWN_MS;
  const outcome = correct ? 'correct' : 'wrong';
  if (waitsForNext(after, outcome)) return null;
  return correct ? SPEED_RIGHT_SHOWN_MS : WRONG_SHOWN_MS;
}

/** This device's choice. */
export async function loadAfterAnswer(): Promise<AfterAnswer> {
  return afterAnswerOf(await getMeta('afterAnswer'));
}

/** Keeps a choice on this device. */
export async function saveAfterAnswer(after: AfterAnswer): Promise<void> {
  await setMeta('afterAnswer', after);
}
