/**
 * The introduction's answers (why the learner learns, where they meet
 * words) go to the account once it exists: `PUT /me/onboarding`, so the
 * operators can see what learners need. Nothing is sent before there is an
 * account (the draft never leaves the tab); the first card writes them to
 * meta `onboardingAnswers` and this sends them, then and on each later
 * start while they wait, and forgets them once the server has answered.
 *
 * It must be safe before the API knows the endpoint: a 404 (an older
 * server), being offline, a server error, a 429 or a session that is
 * refreshing keeps them for the next start. A 400 means they will never be
 * taken and drops them. The server keeps the first answer and says 204 to a
 * repeat, so sending twice is harmless. Answers older than ANSWERS_KEEP_DAYS
 * are let go unsent: a server that has not taken them by then never will.
 */
import { me } from '@/api/endpoints.js';
import { newIdempotencyKey } from '@/api/client.js';
import { isApiError } from '@/api/errors.js';
import { getMeta, setMeta } from '@/db/schema.js';

/** How long unsent answers are kept and tried again, from when they were given. */
export const ANSWERS_KEEP_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

let sending: Promise<void> | undefined;

/** Sends the waiting answers, if any. One send at a time; never throws. */
export function sendOnboardingAnswers(now: number = Date.now()): Promise<void> {
  sending ??= (async () => {
    const waiting = await getMeta('onboardingAnswers');
    if (waiting === null) return;
    const at = Date.parse(waiting.at);
    if (!Number.isFinite(at) || now - at > ANSWERS_KEEP_DAYS * DAY_MS) {
      await setMeta('onboardingAnswers', null);
      return;
    }
    try {
      await me.saveOnboardingAnswers(
        { goals: [...waiting.goals], sources: [...waiting.sources] },
        newIdempotencyKey(),
      );
    } catch (error) {
      const later =
        isApiError(error, 'notFound') ||
        isApiError(error, 'offline') ||
        isApiError(error, 'server') ||
        isApiError(error, 'tooMany') ||
        isApiError(error, 'unauthenticated');
      if (later || !isApiError(error)) return;
    }
    await setMeta('onboardingAnswers', null);
  })()
    .catch(() => undefined)
    .finally(() => {
      sending = undefined;
    });
  return sending;
}
