import { useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { auth as authApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import styles from './SignIn.module.css';

const MIN_PASSWORD = 8;

/**
 * Where the reset link lands. The new password goes to the API with the
 * token; on success every session of the account is already signed out, so
 * the only way on is to sign in again.
 */
export function ResetPassword(): React.JSX.Element {
  const [params] = useSearchParams();
  const token = params.get('token') ?? '';
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState<string | undefined>(token === '' ? t('auth.linkInvalid') : undefined);

  const submit: React.SubmitEventHandler<HTMLFormElement> = (event) => {
    event.preventDefault();
    if (password.length < MIN_PASSWORD) {
      setError(t('auth.passwordShort'));
      return;
    }
    setBusy(true);
    setError(undefined);
    authApi
      .resetPassword(token, password)
      .then(() => {
        setDone(true);
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'offline')) setError(t('error.offline'));
        else if (cause instanceof ApiError && cause.code === 'link_invalid') setError(t('auth.linkInvalid'));
        else if (cause instanceof ApiError && cause.code === 'weak_password') setError(cause.message);
        else setError(t('error.generic'));
      })
      .finally(() => {
        setBusy(false);
      });
  };

  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('app.name')}</h1>
      </div>
      <form className={styles.form} onSubmit={submit} noValidate>
        <div className={styles.formTitle}>{t('auth.resetTitle')}</div>
        {done ? (
          <>
            <p className={styles.success} role="status">
              {t('auth.resetDone')}
            </p>
            <Link to="/auth" className={styles.submit}>
              {t('auth.signIn')}
            </Link>
          </>
        ) : (
          <>
            <p className={styles.lead}>{t('auth.resetLead')}</p>
            <input
              className={styles.input}
              type="password"
              placeholder={t('auth.newPassword')}
              aria-label={t('auth.newPassword')}
              autoComplete="new-password"
              value={password}
              disabled={token === ''}
              onChange={(event) => {
                setPassword(event.target.value);
              }}
            />
            {error !== undefined && (
              <div className={styles.error} role="alert">
                {error}
              </div>
            )}
            <button type="submit" className={styles.submit} disabled={busy || token === ''}>
              {busy ? t('auth.busy') : t('auth.resetSubmit')}
            </button>
            <Link to={token === '' ? '/forgot' : '/auth'} className={styles.textLink}>
              {token === '' ? t('auth.forgotTitle') : t('auth.backToSignIn')}
            </Link>
          </>
        )}
      </form>
    </main>
  );
}
