import { useEffect } from 'react';
import { Button } from '@/components/ui/Button.js';
import { noteTrouble } from '@/features/review/review.js';
import { keepForNextStart } from '@/features/activity/events.js';
import { useAuth } from '@/features/auth/session.js';
import { eventFor } from '@/lib/surface.js';
import { t } from '@/i18n/index.js';
import styles from './Crashed.module.css';

/**
 * What the whole app shows when a render throws. Local data is untouched,
 * so a reload is the honest fix; the error has already been reported.
 */
function crashEvent() {
  return eventFor({ name: 'client.error', meta: { kind: 'crash_recovered' } });
}

export function Crashed(): React.JSX.Element {
  // Nobody who just saw this is asked for a store rating today.
  useEffect(() => {
    noteTrouble();
    // §9 `client.error`: the app showed this screen (the error itself went to Sentry).
    // It is stored for the account and goes with the next start (the reload).
    void keepForNextStart(
      crashEvent(),
      useAuth.getState().status === 'ready' ? useAuth.getState().user?.id : undefined,
    );
  }, []);
  return (
    <main className={styles.screen} role="alert">
      <h1 className={styles.title}>{t('error.crashTitle')}</h1>
      <p className={styles.body}>{t('error.crashBody')}</p>
      <Button
        size="large"
        onClick={() => {
          window.location.reload();
        }}
      >
        {t('error.reload')}
      </Button>
    </main>
  );
}
