/**
 * Today's side of the Pro trial: which card and which hero line, if any, and
 * the writes that make each of them a once-only moment. The rules are
 * `features/billing/trial.ts`; this hook only gathers what they need and
 * remembers what was shown.
 *
 * It asks for the plan once (`ensure`, the same answer every other screen
 * shares), reads two small things locally (the notes and a word count), and
 * keeps its own clock, renewed at the next moment that changes an answer —
 * the trial's end, the start of its last days — and when the app comes back
 * into view, so a tab left open across the end does not keep saying "until".
 */
import { useEffect, useState } from 'react';
import type { ApiBillingState } from '@/api/types.js';
import type { StoredTrialNotes } from '@/db/schema.js';
import { db, getMeta, setMeta } from '@/db/schema.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useAuth } from '@/features/auth/session.js';
import { useBilling } from '@/features/billing/state.js';
import {
  TRIAL_QUIET_HOURS,
  endedTrial,
  runningSchedule,
  runningTrial,
  trialCard,
  trialEndingLine,
  trialRanOut,
  trialSince,
  trialVoiced,
  type EndedTrial,
  type RunningTrial,
  type TrialCardKind,
  type TrialSchedule,
} from '@/features/billing/trial.js';
import { noteTrialEndScreen, trialEndScreen, type TrialEndMoment } from '@/features/billing/trialEnd.js';

const HOUR_MS = 3_600_000;
const DAY_MS = 24 * HOUR_MS;
/** The longest a browser timer can wait; anything further is checked again then. */
const MAX_TIMER_MS = 2_147_483_647;

/**
 * Moments already put on screen in this run of the app. A card shown once
 * stays while the app is open — coming back to Today from a word must not
 * make it vanish — and is gone the next time the app starts. Per tab, which
 * is the point: a second tab opened later sees the notes and stays quiet.
 */
const held = new Set<TrialCardKind | 'ending'>();

/** Whether the plan was read again after a trial ran out, once per run. */
let reReadAfterEnd = false;

/** For tests: forget this run's held moments. */
export function forgetHeldTrialMoments(): void {
  held.clear();
  reReadAfterEnd = false;
}

export interface TrialMoments {
  /** The plan the moments are drawn from: the server's, else the one kept on this device. */
  state: ApiBillingState | null;
  /** Whether what decides the moments has been read here (local reads only). */
  settled: boolean;
  card: TrialCardKind | undefined;
  /** The hero's "ends on" line wants to show. */
  endingLine: boolean;
  /** The trial-end screen wants to open on this visit (`billing/trialEnd.ts`). */
  endScreen: TrialEndMoment | undefined;
  running: RunningTrial | undefined;
  /** When the running trial's moments come, by its own length; undefined when not known. */
  schedule: TrialSchedule | undefined;
  ended: EndedTrial | undefined;
  /** Whether the learner has used Paste a text or Read a text on this device. */
  pasted: boolean;
  now: Date;
  /**
   * The card was answered: its button, Not now (which also hides the next
   * offer card), or "Don't remind me". Gone for good.
   */
  answer: (kind: TrialCardKind, how?: 'action' | 'notNow') => void;
}

interface Local {
  notes: StoredTrialNotes;
  words: number;
  pasted: boolean;
}

async function loadLocal(): Promise<Local> {
  const [notes, words, pasteUses] = await Promise.all([
    getMeta('trialNotes'),
    db.words.count(),
    getMeta('pasteUses'),
  ]);
  return { notes, words, pasted: pasteUses > 0 };
}

/** Writes one change to the notes, read inside the write so two tabs cannot undo each other. */
async function note(patch: (notes: StoredTrialNotes) => StoredTrialNotes | undefined): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    const next = patch(await getMeta('trialNotes'));
    if (next !== undefined) await setMeta('trialNotes', next);
  });
}

/** The next instant at which an answer here can change, or undefined for none. */
function nextBoundary(
  now: number,
  running: RunningTrial | undefined,
  since: Date | undefined,
): number | undefined {
  const points: number[] = [];
  if (since !== undefined) points.push(since.getTime() + TRIAL_QUIET_HOURS * HOUR_MS);
  if (running !== undefined) {
    points.push(running.endsAt.getTime());
    const schedule = runningSchedule(running, since);
    const start = running.startedAt ?? since;
    if (schedule !== undefined && start !== undefined) {
      points.push(
        running.endsAt.getTime() - schedule.ending * DAY_MS,
        start.getTime() + schedule.meetLex * DAY_MS,
        start.getTime() + schedule.midway * DAY_MS,
        start.getTime() + schedule.half * DAY_MS,
      );
    }
  }
  const ahead = points.filter((point) => point > now);
  return ahead.length === 0 ? undefined : Math.min(...ahead);
}

/**
 * `notebook` is the one in view, undefined when there is none, and null
 * while it is still being read: until its languages are known nothing is
 * decided, or a notebook Lexpad never charges for would be shown a card for
 * the frames before they are.
 */
export function useTrialMoments(
  notebook: { targetLang: string; meaningLang: string } | undefined | null,
  /**
   * The account's last plan kept on this device, read with the page: on a
   * cold start, before the server has answered, the moments are drawn from
   * it (checked against the clock like any plan) so they land with the page.
   */
  kept?: ApiBillingState,
  /** A celebration has this visit: the trial-end screen waits for the next one. */
  celebrating = false,
): TrialMoments {
  const live = useBilling((s) => s.state);
  const state = live ?? kept ?? null;
  const checked = useBilling((s) => s.checked);
  const ensure = useBilling((s) => s.ensure);
  const refresh = useBilling((s) => s.refresh);
  const createdAt = useAuth((s) => s.user?.createdAt);
  const local = useLiveQuery<Local | null>(loadLocal, null, []);
  const [now, setNow] = useState(() => new Date());
  // Whether the plan was in hand as this visit to Today began (the app asks
  // for it as it opens). A card or a line that depends on it is drawn with
  // the rest of the page or not at all on this visit: arriving later, it
  // would push the page down under the reader. It waits for the next visit
  // instead — back from a session, or the next start of the app.
  const [planAtStart] = useState(() => useBilling.getState().checked);

  useEffect(() => {
    ensure();
  }, [ensure]);

  const notes = local?.notes ?? {};
  // The trial's own start when the server says it, else the account's creation.
  const since = trialSince(state?.trial?.startedAt ?? createdAt, notes);
  const running = runningTrial(state, now);
  const ended = endedTrial(state);

  // The clock moves at the next moment that matters, and on coming back.
  const boundary = nextBoundary(now.getTime(), running, since);
  useEffect(() => {
    const renew = (): void => {
      setNow(new Date());
    };
    const timer =
      boundary === undefined
        ? undefined
        : window.setTimeout(renew, Math.min(MAX_TIMER_MS, Math.max(0, boundary - Date.now()) + 1));
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') renew();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [boundary]);

  // A copy of the plan from before the end still names the trial: read it
  // once more, so the card about the end can come.
  const ranOut = trialRanOut(state, now);
  useEffect(() => {
    if (!ranOut || reReadAfterEnd) return;
    reReadAfterEnd = true;
    void refresh();
  }, [ranOut, refresh]);

  // The first sight of a running trial on this device, for an account whose
  // creation this device does not know yet.
  const firstSeenMissing = local !== null && running !== undefined && notes.firstSeen === undefined;
  useEffect(() => {
    if (!firstSeenMissing) return;
    const at = new Date().toISOString();
    void note((current) => (current.firstSeen === undefined ? { ...current, firstSeen: at } : undefined));
  }, [firstSeenMissing]);

  // Settled is local only (the notes, the words, the notebook in view): the
  // place on Today never waits for the network.
  const settled = local !== null && notebook !== null;
  // A plan in hand as the visit began, or the kept one read with the page:
  // either way the moments land with the page, never after it.
  const decides = settled && ((planAtStart && checked) || (live === null && kept !== undefined));
  const signals = {
    now,
    since,
    words: local?.words ?? 0,
    notes,
    held,
    voiced: trialVoiced(state, notebook?.targetLang, notebook?.meaningLang),
  };
  const card = decides ? trialCard(state, signals) : undefined;
  const endingLine = decides && trialEndingLine(state, signals);
  // Only from the live plan: a full screen with a price never opens on a kept copy.
  const endScreen =
    decides && live !== null
      ? trialEndScreen(live, { now, notes, voiced: signals.voiced, celebrating })
      : undefined;

  return {
    state,
    settled,
    card,
    endingLine,
    endScreen,
    running,
    schedule: running === undefined ? undefined : runningSchedule(running, since),
    ended,
    pasted: local?.pasted === true,
    now,
    answer: (kind, how = 'action') => {
      held.delete(kind);
      const notNow = how === 'notNow' ? { notNow: true } : {};
      if (kind === 'ended') {
        const key = ended?.key;
        if (key !== undefined)
          void note((current) => ({ ...current, ...notNow, endSeen: key, endDone: key }));
        return;
      }
      void note((current) => ({ ...current, ...notNow, ...runningNotes(kind, true) }));
    },
  };
}

/**
 * Marks a card as shown once it is actually on screen. Called by the card
 * itself, on mount, so a card that lost its place to another (a nudge
 * already shown this session) is not counted as seen.
 */
export function markTrialCardShown(kind: TrialCardKind, endedKey: string | undefined): void {
  held.add(kind);
  if (kind !== 'ended') {
    void note((current) =>
      current[runningNotes(kind, false).seenKey] === true
        ? undefined
        : { ...current, ...runningNotes(kind, false) },
    );
    return;
  }
  if (endedKey !== undefined) {
    void note((current) => (current.endSeen === endedKey ? undefined : { ...current, endSeen: endedKey }));
  }
}

/** The notes that say a running-trial card was seen (and, with `done`, answered). */
function runningNotes(
  kind: Exclude<TrialCardKind, 'ended'>,
  done: boolean,
): Partial<StoredTrialNotes> & { seenKey: 'meetLexSeen' | 'midwaySeen' | 'weekSeen' } {
  switch (kind) {
    case 'meetLex':
      return { seenKey: 'meetLexSeen', meetLexSeen: true, ...(done ? { meetLexDone: true } : {}) };
    case 'midway':
      return { seenKey: 'midwaySeen', midwaySeen: true, ...(done ? { midwayDone: true } : {}) };
    case 'week':
      return { seenKey: 'weekSeen', weekSeen: true, ...(done ? { weekDone: true } : {}) };
  }
}

/** Marks the hero's "ends on" line as shown, once it is on screen. */
export function markTrialEndingShown(endsAtKey: string): void {
  held.add('ending');
  void note((current) =>
    current.endingSeen === endsAtKey ? undefined : { ...current, endingSeen: endsAtKey },
  );
}

/** Marks the trial-end screen as shown, once it is on screen: it does not open again for this trial. */
export function markTrialEndScreenShown(moment: TrialEndMoment): void {
  void note((current) => {
    const next = noteTrialEndScreen(current, moment);
    return next.endScreen === current.endScreen && next.lastDayScreen === current.lastDayScreen
      ? undefined
      : next;
  });
}
