import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import styles from './Spinner.module.css';

/**
 * A centred loading state, for the rare screen that must wait. `page` centres
 * it in the whole screen, clear of the notch, for a wait before any screen.
 */
export function Spinner({
  label,
  page = false,
}: {
  label?: string | undefined;
  page?: boolean;
}): React.JSX.Element {
  return (
    <div className={cx(styles.wrap, page && styles.page)} role="status">
      <span className={styles.dot} aria-hidden="true" />
      <span className={styles.label}>{label ?? t('state.loading')}</span>
    </div>
  );
}

/**
 * A placeholder with the same geometry as the content it stands in for, so
 * nothing shifts when the data arrives.
 */
export function Skeleton({ height, width }: { height: number; width?: number | string }): React.JSX.Element {
  return (
    <span
      className={styles.skeleton}
      style={{ display: 'block', height, width: width ?? '100%' }}
      aria-hidden="true"
    />
  );
}
