/**
 * Tells a copy of Lexpad that nobody else updates that a newer one exists.
 * The stores do this for their apps; an APK installed from lexpad.app, and
 * the desktop app on a Mac or a Windows PC, have nobody to tell them, so
 * once a day the app reads a tiny version file from the site and remembers
 * the answer. Nothing is sent, and a failure is silent: an old build keeps
 * working, it just does not know it is old.
 *
 * - **Android** (sideloaded builds) reads the file itself.
 * - **The desktop app** asks its core (`latest_release`), because its
 *   window may not reach the network on its own; the core reads the same
 *   file and says which system this is and, on Windows, whether this copy
 *   came from the Microsoft Store.
 */
import { getMeta, setMeta } from '@/db/schema.js';
import { MICROSOFT_STORE_URL, SITE_HOST, safeExternalUrl } from './externalLinks.js';
import { platform } from './platform/index.js';
import type { DesktopRelease, DesktopReleases } from './platform/types.js';

export const VERSION_URL = `https://${SITE_HOST}/version.json`;
/** How long a check stands before the file is read again. */
export const CHECK_EVERY_MS = 24 * 60 * 60 * 1000;

export interface UpdateInfo {
  version: string;
  url: string;
}

interface VersionFile {
  android?: { versionName?: string; url?: string };
}

/** Whether `candidate` is a higher dotted version than `current`. */
export function isNewer(candidate: string, current: string): boolean {
  const a = candidate.split('.').map((part) => Number.parseInt(part, 10));
  const b = current.split('.').map((part) => Number.parseInt(part, 10));
  if (a.some(Number.isNaN) || b.some(Number.isNaN)) return false;
  for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
    const x = a[i] ?? 0;
    const y = b[i] ?? 0;
    if (x !== y) return x > y;
  }
  return false;
}

function isDesktop(): boolean {
  return platform.env.embedded && platform.env.platform === 'desktop' && platform.desktop !== undefined;
}

/**
 * The newer build to offer, or null. Reads the site at most once a day and
 * only inside the Android shell and the desktop app; the web app updates
 * itself and iOS comes from a store. The desktop app's answer is kept for
 * `desktopOffer`, which decides what to offer, and this resolves null there.
 */
export async function checkForUpdate(
  now: number = Date.now(),
  fetchFn: typeof fetch = (input, init) => fetch(input, init),
): Promise<UpdateInfo | null> {
  if (isDesktop()) {
    await checkForDesktopUpdate(now);
    return null;
  }
  if (!platform.env.embedded || platform.env.platform !== 'android') return null;
  const current = platform.env.appVersion;
  const known = await getMeta('updateCheck');
  if (known !== null && now - known.at < CHECK_EVERY_MS) {
    return isNewer(known.version, current) ? { version: known.version, url: known.url } : null;
  }
  if (!platform.network.online) return null;
  let latest: UpdateInfo | undefined;
  try {
    const response = await fetchFn(VERSION_URL, { cache: 'no-store' });
    if (!response.ok) return null;
    const file = (await response.json()) as VersionFile;
    const version = file.android?.versionName;
    const url = file.android?.url;
    if (typeof version !== 'string' || typeof url !== 'string') return null;
    // The banner opens this address, so a file that names anywhere but the
    // site's own download page is treated as no file at all.
    const safe = safeExternalUrl(url, 'update');
    if (safe === undefined) return null;
    latest = { version, url: safe.href };
  } catch {
    return null;
  }
  await setMeta('updateCheck', { at: now, ...latest });
  return isNewer(latest.version, current) ? latest : null;
}

/**
 * Asks the desktop core for the site's desktop versions, at most once a day,
 * and keeps the answer. Offline, or with the site out of reach, nothing
 * changes: the last answer stands and the next check tries again.
 */
export async function checkForDesktopUpdate(now: number = Date.now()): Promise<void> {
  const host = platform.desktop;
  if (!isDesktop() || host === undefined) return;
  const known = await getMeta('desktopRelease');
  if (known !== null && now - known.at < CHECK_EVERY_MS) return;
  if (!platform.network.online) return;
  let release: DesktopRelease;
  try {
    release = await host.latestRelease();
  } catch {
    return;
  }
  await setMeta('desktopRelease', { at: now, release });
}

/** One button of the update line: where it goes and what it says. */
export interface UpdateLink {
  /** `download`: the site's download page; `microsoftStore`: the Store's listing. */
  kind: 'download' | 'microsoftStore';
  url: string;
}

/** A newer desktop version to offer, with its buttons in the order to show them. */
export interface DesktopOffer {
  version: string;
  links: UpdateLink[];
}

/** A dotted version of numbers, as the site writes them. */
function isVersion(value: unknown): value is string {
  return typeof value === 'string' && /^\d+(\.\d+){0,3}$/.test(value);
}

/** The site's download page, at the box that starts the download (the site's rule for a Download button). */
function downloadPage(raw: unknown): string | undefined {
  const url = safeExternalUrl(raw, 'update');
  if (url === undefined) return undefined;
  url.hash = 'start';
  return url.href;
}

/**
 * What the update line offers on this computer, or null.
 *
 * - **Mac**: the version of the Mac download, and its download page.
 * - **Windows, installed from lexpad.app**: the version of the Windows
 *   download; its page first, then the Microsoft Store if the Store already
 *   serves that version.
 * - **Windows, from the Microsoft Store**: only a version the Store serves
 *   (it can lag behind the direct download while a submission is
 *   certified), since the Store is what updates this copy; the Store first,
 *   then the download page if it has that version too.
 *
 * Addresses are checked here (the site's own pages; the Store's listing is
 * written in code), so a tampered file can only ever name a version.
 */
export function desktopOffer(release: DesktopRelease, current: string): DesktopOffer | null {
  const files: DesktopReleases = release.releases;
  if (release.os === 'macos') {
    const mac = files.mac;
    const url = downloadPage(mac?.url);
    if (mac === undefined || !isVersion(mac.version) || url === undefined) return null;
    if (!isNewer(mac.version, current)) return null;
    return { version: mac.version, links: [{ kind: 'download', url }] };
  }
  if (release.os !== 'windows') return null;
  const direct = files.windows;
  const directUrl = downloadPage(direct?.url);
  const store = files.msStore;
  const storeUrl = safeExternalUrl(MICROSOFT_STORE_URL, 'store')?.href;
  const choices: { version: string; link: UpdateLink }[] = [];
  if (direct !== undefined && isVersion(direct.version) && directUrl !== undefined) {
    choices.push({ version: direct.version, link: { kind: 'download', url: directUrl } });
  }
  if (store !== undefined && isVersion(store.version) && storeUrl !== undefined) {
    const entry = { version: store.version, link: { kind: 'microsoftStore' as const, url: storeUrl } };
    if (release.install === 'store') choices.unshift(entry);
    else choices.push(entry);
  }
  // The way this copy updates decides the version; any other way is offered
  // beside it only when it has that version too.
  const own = choices[0];
  if (own === undefined) return null;
  if (release.install === 'store' && own.link.kind !== 'microsoftStore') return null;
  if (release.install !== 'store' && own.link.kind !== 'download') return null;
  if (!isNewer(own.version, current)) return null;
  const links = choices.filter((c) => !isNewer(own.version, c.version)).map((c) => c.link);
  return { version: own.version, links };
}
